3	2300	1	1	1	{"en_US": "Tip: A calculator in Odoo"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: A calculator in Odoo</p>\\n    <p class=\\"tip_content\\">When editing a number, you can use formulae by typing the `=` character. This is useful when computing a margin or a discount on a quotation, sale order or invoice.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-calculator.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:03:36.539773	2026-04-14 18:03:36.539773
4	2400	1	1	1	{"en_US": "Tip: How to ping users in internal notes?"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: How to ping users in internal notes?</p>\\n    <p class=\\"tip_content\\">Type \\"@\\" to notify someone in a message, or \\"#\\" to link to a channel. Try to notify @OdooBot to test the feature.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-notifications.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:03:36.539773	2026-04-14 18:03:36.539773
5	2500	1	1	1	{"en_US": "Tip: Knowledge is power"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Knowledge is power</p>\\n    <p class=\\"tip_content\\">When following documents, use the pencil icon to fine-tune the information you want to receive.\\nFollow a project / sales team to keep track of this project's tasks / this team's opportunities.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-following.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:03:36.539773	2026-04-14 18:03:36.539773
7	1900	1	1	1	{"en_US": "Tip: Navigate menus like a pro"}	{"en_US": "<div>\\n                    <b class=\\"tip_title\\">Tip: Navigate menus like a pro</b>\\n                    <p class=\\"tip_content\\">From the Home page, start typing what you would like to access. Odoo will suggest menus matching your search. Use arrow keys and press enter to jump to your menu.</p>\\n                    <img src=\\"https://download.odoocdn.com/digests/digest_enterprise/static/src/img/menu-navigation.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n                </div>\\n            "}	2026-04-14 18:04:19.547096	2026-04-14 18:04:19.547096
10	2200	35	1	1	{"en_US": "Tip: Odoo supports configurable products"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Odoo supports configurable products</p>\\n    <p class=\\"tip_content\\">Struggling with a complex product catalog? Try out the Product Configurator to help sales configure a product with different options: colors, size, capacity, etc. Make sale orders encoding easier and error-proof.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/sale_management/static/src/img/milk-Sales-configure-products.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:06:05.105899	2026-04-14 18:06:05.105899
11	2700	35	1	1	{"en_US": "Tip: Sell or buy products in bulk with matrixes"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Sell or buy products in bulk with matrixes</p>\\n    <p class=\\"tip_content\\">Selling the same product in different sizes or colors? Try the product grid and populate your orders with multiple quantities of each variant. This feature also exists in the Purchase application.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/sale_management/static/src/img/milk-t-shirts.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:06:05.105899	2026-04-14 18:06:05.105899
1	800	1	1	1	{"en_US": "Tip: Speed up your workflow with shortcuts"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Speed up your workflow with shortcuts</p>\\n    <p class=\\"tip_content\\">Press ALT in any screen to highlight shortcuts for every button in the screen. It is useful to process multiple documents in batch.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-alt-shortcuts.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:03:36.539773	2026-04-29 07:24:49.280505
8	900	24	1	1	{"en_US": "Tip: Bulk update journal items"}	{"en_US": "<div>\\n    <b class=\\"tip_title\\">Tip: Bulk update journal items</b>\\n    <p class=\\"tip_content\\">From any list view, select multiple records and the list becomes editable. If you update a cell, selected records are updated all at once. Use this feature to update multiple journal entries from the General Ledger, or any Journal view.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account_accountant/static/src/img/accounting-bulk.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:04:22.189709	2026-05-10 06:27:25.489122
9	1000	24	1	1	{"en_US": "Tip: Find an Accountant or register your Accounting Firm"}	{"en_US": "<div>\\n    <b class=\\"tip_title\\">Tip: Find an Accountant or register your Accounting Firm</b>\\n    <p class=\\"tip_content\\">Click here to find an accountant or if you want to list out your accounting services on Odoo</p>\\n    <p class=\\"mt-3\\">\\n        <a class=\\"tip_button\\" href=\\"https://odoo.com/accounting-firms\\" target=\\"_blank\\"><span class=\\"tip_button_text\\">Find an Accountant</span></a>\\n        <a class=\\"tip_button\\" href=\\"https://odoo.com/accounting-firms/register\\" target=\\"_blank\\"><span class=\\"tip_button_text\\">Register your Accounting Firm</span></a>\\n    </p>\\n</div>\\n            "}	2026-04-14 18:04:22.189709	2026-07-05 14:49:26.73922
12	1000	42	1	1	{"en_US": "Tip: Speed up inventory operations with barcodes"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Speed up inventory operations with barcodes</p>\\n    <table class=\\"tip_twocol\\">\\n        <tr>\\n            <td class=\\"tip_twocol_left\\" style=\\"width: 45%;\\">\\n                <img src=\\"https://download.odoocdn.com/digests/stock/static/src/img/barcode.gif\\" class=\\"tip_twocol_img\\" width=\\"240\\">\\n            </td>\\n            <td style=\\"width: 55%;\\">\\n                <p class=\\"tip_content\\" style=\\"margin: 0;\\">Enjoy a quick-paced experience with the Odoo barcode app. It is blazing fast and works even without a stable internet connection. It supports all flows: inventory adjustments, batch picking, moving lots or pallets, low inventory checks, etc. Go to the \\"Apps\\" menu to activate the barcode interface.</p>\\n            </td>\\n        </tr>\\n    </table>\\n    <div style=\\"clear: both;\\"></div>\\n</div>\\n            "}	2026-04-14 18:09:21.967471	2026-08-05 20:03:54.937064
13	1500	59	1	1	{"en_US": "Tip: Engage with visitors to convert them into leads"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Engage with visitors to convert them into leads</p>\\n    <p class=\\"tip_content\\">Monitor your visitors while they are browsing your website with the Odoo Social app. Engage with them in just a click using a live chat request or a push notification. If they have completed one of your forms, you can send them an SMS, or call them right away while they are browsing your website.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/website/static/src/img/milk-website-visitors.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:11:46.315853	2026-04-14 18:11:46.315853
14	1400	59	1	1	{"en_US": "Tip: Use royalty-free photos"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Use royalty-free photos</p>\\n    <p class=\\"tip_content\\">Search in the media dialogue when you need photos to illustrate your website. Odoo's integration with Unsplash, featuring millions of royalty free and high quality photos, makes it possible for you to get the perfect picture, in just a few clicks.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/website/static/src/img/milk-image-search.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:11:46.315853	2026-04-14 18:11:46.315853
15	1600	59	1	1	{"en_US": "Tip: Search Engine Optimization (SEO)"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Search Engine Optimization (SEO)</p>\\n    <p class=\\"tip_content\\">To get more visitors, you should target keywords that are often searched in Google. With the built-in SEO tool, once you define a few keywords, Odoo will recommend you the best keywords to target. Then adapt your title and description accordingly to boost your traffic.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/website/static/src/img/milk-SEO-keywords.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:11:46.315853	2026-04-14 18:11:46.315853
19	2000	63	1	1	{"en_US": "Tip: Never miss a purchase order"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Never miss a purchase order</p>\\n    <p class=\\"tip_content\\">When sending a purchase order by email, Odoo asks the vendor to acknowledge the reception of the order. When the vendor acknowledges the order by clicking on a button in the email, the information is added on the purchase order. Use filters to track orders that have not been acknowledged.</p>\\n</div>\\n            "}	2026-04-14 18:12:07.344559	2026-04-14 18:12:07.344559
18	100	63	1	1	{"en_US": "Tip: How to keep late receipts under control?"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: How to keep late receipts under control?</p>\\n    <p class=\\"tip_content\\">When creating a purchase order, have a look at the vendor's <i>On Time Delivery</i> rate: the percentage of products shipped on time. If it is too low, activate the <i>automated reminders</i>. A few days before the due shipment, Odoo will send the vendor an email to ask confirmation of shipment dates and keep you informed in case of any delays. To get the vendor's performance statistics, click on the OTD rate.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/purchase/static/src/img/milk-OTDPurchase.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:12:07.344559	2026-04-14 20:03:53.957637
16	300	59	1	1	{"en_US": "Tip: Use illustrations to spice up your website"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Use illustrations to spice up your website</p>\\n    <p class=\\"tip_content\\">Not only can you search for royalty-free illustrations, their colors are also converted so that they always fit your Theme.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/website/static/src/img/milk-website-illustrations.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:11:46.315853	2026-04-17 14:08:31.327907
17	400	59	1	1	{"en_US": "Tip: Add shapes to energize your Website"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Add shapes to energize your Website</p>\\n    <p class=\\"tip_content\\">More than 90 shapes exist and their colors are picked to match your Theme.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/website/static/src/img/milk-website-shapes.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:11:46.315853	2026-04-18 11:17:30.277568
6	700	23	1	1	{"en_US": "Tip: No need to print, put in an envelop and post your invoices"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: No need to print, put in an envelop and post your invoices</p>\\n    <p class=\\"tip_content\\">Use the “<i>Send by Post</i>” option to post invoices automatically. For the cost of a local stamp, we do all the manual work: your invoice will be printed in the right country, put in an envelop and sent by snail mail. Use this feature from the list view to post hundreds of invoices in bulk.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/invoice-stamps.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-04-14 18:03:48.246619	2026-04-19 20:03:40.168712
