 by additional group rules.\\n                      </p>\\n                      <p>\\n                        Detailed algorithm:\\n                        <ol>\\n                          <li>Global rules are combined together with a logical AND operator, and with the result of the following steps</li>\\n                          <li>Group-specific rules are combined together with a logical OR operator</li>\\n                          <li>If user belongs to several groups, the results from step 2 are combined with logical OR operator</li>\\n                        </ol>\\n                      </p>\\n                      <p>Example: GLOBAL_RULE_1 AND GLOBAL_RULE_2 AND ( (GROUP_A_RULE_1 OR GROUP_A_RULE_2) OR (GROUP_B_RULE_1 OR GROUP_B_RULE_2) )</p>\\n                    </div>\\n                   </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Record rules">\n                  <sheet>\n                    <group>\n                        <group string="General">\n                            <field name="name"/>\n                            <field name="model_id"/>\n                            <field name="active" widget="boolean_toggle"/>\n                        </group>\n                        <group string="Access Rights">\n                            <group>\n                                <field name="perm_read"/>\n                                <field name="perm_create"/>\n                            </group>\n                            <group>\n                                <field name="perm_write"/>\n                                <field name="perm_unlink"/>\n                            </group>\n                        </group>\n                    </group>\n                    <separator string="Rule Definition (Domain Filter)"/>\n                    <field name="domain_force" colspan="2" nolabel="1"/>\n                    <group string="Groups (no group = global)">\n                        <field name="global"/>\n      