 name="digest_email_setting_container">\n                            <field name="digest_emails"/>\n                            <div class="content-group" invisible="not digest_emails">\n                                <div class="mt16">\n                                    <label for="digest_id" class="o_light_label mr8"/>\n                                    <field name="digest_id" class="oe_inline"/>\n                                </div>\n                                <div class="mt8">\n                                    <button type="action" name="201" string="Configure Digest Emails" icon="oi-arrow-right" class="btn-link"/>\n                                </div>\n                            </div>\n                        </setting>\n                    </block>\n                </div>\n            </xpath>\n        	f	t	2026-04-14 18:03:36.539773	2026-04-14 18:03:36.539773	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
