1383	16	\N	1	1	Submenu	\N	website.submenu	qweb	website/views/website_templates.xml	primary	{"en_US": "<t name=\\"Submenu\\" t-name=\\"website.submenu\\">\\n    <t t-set=\\"show_dropdown\\" t-value=\\"(submenu.is_mega_menu and submenu.is_visible) or submenu.child_id.filtered(lambda menu: menu.is_visible)\\"/>\\n    <li t-if=\\"submenu.is_visible and not (submenu.child_id or submenu.is_mega_menu)\\" t-attf-class=\\"#{item_class or ''}\\" role=\\"presentation\\">\\n        <a t-att-href=\\"submenu._clean_url()\\" t-attf-class=\\"#{link_class or ''} #{submenu._is_active() and 'active'}\\" role=\\"menuitem\\" t-ignore=\\"true\\" t-att-target=\\"'_blank' if submenu.new_window else None\\">\\n            <span t-field=\\"submenu.name\\"/>\\n        </a>\\n    </li>\\n    <li t-elif=\\"show_dropdown\\" t-attf-class=\\"#{item_class or ''} dropdown #{submenu.is_mega_menu and 'position-static'}\\" role=\\"presentation\\">\\n        <a t-attf-class=\\"#{link_class or ''} dropdown-toggle #{submenu.is_mega_menu and 'o_mega_menu_toggle'} #{submenu._is_active() and 'active'} #{dropdown_toggler_classes}\\" data-bs-toggle=\\"dropdown\\" href=\\"#\\" t-att-data-bs-display=\\"'static' if submenu.is_mega_menu else None\\" role=\\"menuitem\\">\\n            <span t-field=\\"submenu.name\\"/>\\n        </a>\\n        <div t-if=\\"submenu.is_mega_menu and not is_mobile\\" t-attf-class=\\"dropdown-menu o_mega_menu #{submenu.mega_menu_classes}\\" data-name=\\"Mega Menu\\" t-field=\\"submenu.mega_menu_content\\"/>\\n        <!--\\n            TODO remove the next two if elements in master, this was made to not\\n            have to change the \\"else\\" element in stable and prevent xpath fails\\n            on the existing elements.\\n            -> The first one render nothing (case submenu.is_mega_menu and is_mobile)\\n            -> The second one is never considered (t-elif evaluated first)\\n        -->\\n        <t t-elif=\\"submenu.is_mega_menu\\"/>\\n        <div t-if=\\"submenu.is_mega_menu\\" t-elif=\\"False\\" t-attf-class=\\"dropdown-menu o_mega_menu #{submenu.mega_menu_classes}\\" data-name=\\"Mega Menu\\" t-field=\\"submenu.mega_menu_content\\" role=\\"menuitem\\"/>\\n        <ul t-else=\\"\\" t-attf-class=\\"dropdown-menu #{dropdown_menu_classes}\\" role=\\"menu\\">\\n            <t t-foreach=\\"submenu.child_id\\" t-as=\\"submenu\\">\\n                <t t-call=\\"website.submenu\\">\\n                    <t t-set=\\"item_class\\" t-value=\\"None\\"/>\\n                    <t t-set=\\"link_class\\" t-valuef=\\"dropdown-item\\"/>\\n                </t>\\n            </t>\\n        </ul>\\n    </li>\\n</t>"}	<?xml version="1.0"?>\n<t name="Submenu" t-name="website.submenu">\n    <t t-set="show_dropdown" t-value="(submenu.is_mega_menu and submenu.is_visible) or submenu.child_id.filtered(lambda menu: menu.is_visible)"/>\n    <li t-if="submenu.is_visible and not (submenu.child_id or submenu.is_mega_menu)" t-attf-class="#{item_class or ''}" role="presentation">\n        <a t-att-href="submenu._clean_url()" t-attf-class="#{link_class or ''} #{submenu._is_active() and 'active'}" role="menuitem" t-ignore="true" t-att-target="'_blank' if submenu.new_window else None">\n            <span t-field="submenu.name"/>\n        </a>\n    </li>\n    <li t-elif="show_dropdown" t-attf-class="#{item_class or ''} dropdown #{submenu.is_mega_menu and 'position-static'}" role="presentation">\n        <a t-attf-class="#{link_class or ''} dropdown-toggle #{submenu.is_mega_menu and 'o_mega_menu_toggle'} #{submenu._is_active() and 'active'} #{dropdown_toggler_classes}" data-bs-toggle="dropdown" href="#" t-att-data-bs-display="'static' if submenu.is_mega_menu else None" role="menuitem">\n            <span t-field="submenu.name"/>\n        </a>\n        <div t-if="submenu.is_mega_menu and not is_mobile" t-attf-class="dropdown-menu o_mega_menu #{submenu.mega_menu_classes}" data-name="Mega Menu" t-field="submenu.mega_menu_content"/>\n        <!--\n            TODO remove the next two if elements in master, this was made to not\n            have to change the "else" element in stable and prevent xpath fails\n            on the existing elements.\n            -> The first one render nothing (case submenu.is_mega_menu and is_mobile)\n            -> The second one is never considered (t-elif evaluated first)\n        -->\n        <t t-elif="submenu.is_mega_menu"/>\n        <div t-if="submenu.is_mega_menu" t-elif="False" t-attf-class="dropdown-menu o_mega_menu #{submenu.mega_menu_classes}" data-name="Mega Menu" t-field="submenu.mega_menu_content" role="menuitem"/>\n        <ul t-else="" t-attf-class="dropdown-menu #{dropdown_menu_classes}" role="menu">\n            <t t-foreach="submenu.child_id" t-as="submenu">\n                <t t-call="website.submenu">\n                    <t t-set="item_class" t-value="None"/>\n                    <t t-set="link_class" t-valuef="dropdown-item"/>\n                </t>\n            </t>\n        </ul>\n    </li>\n</t>\n\n	f	t	2026-04-14 18:11:46.315853	2026-04-14 18:11:46.315853	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
1384	16	514	1	1	Main layout	\N	website.layout	qweb	website/views/website_templates.xml	extension	{"en_US": "<data name=\\"Main layout\\" inherit_id=\\"portal.frontend_layout\\">\\n    <xpath expr=\\"//html\\" position=\\"before\\">\\n        <t t-set=\\"html_data\\" t-value=\\"{             'lang': lang and lang.replace('_', '-'),             'data-website-id': website.id if website else None,             'data-edit_translations': '1' if edit_translations else None,             'data-main-object': repr(main_object) if main_object else None,             'data-seo-object': repr(seo_object) if seo_object else None,         }\\"/>\\n        <t t-if=\\"not request.env.user._is_public()\\" t-set=\\"nothing\\" t-value=\\"html_data.update({             'data-is-published': 'website_published' in main_object.fields_get() and main_object.website_published,             'data-can-optimize-seo': 'website_meta_description' in main_object.fields_get(),             'data-can-publish': 'can_publish' in main_object.fields_get() and main_object.can_publish,             'data-editable-in-backend': edit_in_backend or ('website_published' in main_object.fields_get() and main_object._name != 'website.page'),         })\\"/>\\n        <!--\\n        TODO Review in master (this is a stable fix for new databases).\\n        See REVIEW_CAN_PUBLISH_UNSUDO.\\n        -->\\n        <t t-if=\\"html_data and html_data.get('data-can-publish') == True\\">\\n            <t t-set=\\"nothing\\" t-value=\\"html_data.update({                 'data-can-publish': 'can_publish' in main_object.fields_get() and main_object.sudo(flag=False).can_publish,             })\\"/>\\n        </t>\\n        <t t-if=\\"editable or translatable\\" t-set=\\"nothing\\" t-value=\\"html_data.update({             'data-editable': '1' if editable else None,             'data-translatable': '1' if translatable else None,             'data-view-xmlid': xmlid,             'data-viewid': viewid,         })\\"/>\\n    </xpath>\\n\\n    <xpath expr=\\"//head\\" position=\\"attributes\\">\\n        <!--\\n        Cache the <head> of the website.layout:\\n        - For each individual website.page record (their css/js might be the\\n          same but their title will not for example). Arguably we could do this\\n          for any record (not only website.page) but this t-cache was originally\\n          added to replace the website.page own cache system. For other records,\\n          it could probably depend on each individual access right.\\n        - Only for non-designers (especially visitors) (hence the \\"editable or\\n          translatable\\" check).\\n        - Only if not in any debug mode (we want any correct value of debug mode\\n          to correctly appear in the `odoo` object + assets may depend on this\\n          (e.g. debug=assets or debug=tests)).\\n        -->\\n        <attribute name=\\"t-cache\\">main_object if main_object and main_object._name == 'website.page' and not request.session.debug and not editable and not translatable else None</attribute>\\n    </xpath>\\n    <xpath expr=\\"//head/*[1]\\" position=\\"before\\">\\n        <t t-if=\\"not title\\">\\n            <t t-if=\\"not additional_title and main_object and 'name' in main_object\\">\\n                <t t-set=\\"additional_title\\" t-value=\\"main_object.name\\"/>\\n            </t>\\n            <t t-set=\\"default_title\\" t-translation=\\"off\\" t-value=\\"(additional_title + ' | ' if additional_title else '') + (website or res_company).name\\"/>\\n            <t t-set=\\"seo_object\\" t-value=\\"seo_object or main_object\\"/>\\n            <t t-if=\\"seo_object and 'website_meta_title' in seo_object and seo_object.website_meta_title\\">\\n                <t t-set=\\"title\\" t-value=\\"seo_object.website_meta_title\\"/>\\n            </t>\\n            <t t-else=\\"\\">\\n                <t t-set=\\"title\\" t-value=\\"default_title\\"/>\\n            </t>\\n        </t>\\n        <t t-set=\\"x_icon\\" t-value=\\"website.image_url(website, 'favicon')\\"/>\\n    </xpath>\\n    <xpath expr=\\"//head/meta[last()]\\" position=\\"after\\">\\n        <meta name=\\"generator\\" content=\\"Odoo\\"/>\\n        <t t-set=\\"website_meta\\" t-value=\\"seo_object and seo_object.get_website_meta() or {}\\"/>\\n        <meta name=\\"default_title\\" t-att-content=\\"default_title\\" groups=\\"website.group_website_designer\\"/>\\n        <meta t-if=\\"(main_object and 'website_indexed' in main_object         and not main_object.website_indexed) or (website.domain and not website._is_indexable_url(request.httprequest.url_root))\\" name=\\"robots\\" content=\\"noindex\\"/>\\n        <t t-set=\\"seo_object\\" t-value=\\"seo_object or main_object\\"/>\\n        <t t-set=\\"meta_description\\" t-value=\\"seo_object and 'website_meta_description' in seo_object             and seo_object.website_meta_description or website_meta_description or website_meta.get('meta_description', '')\\"/>\\n        <t t-set=\\"meta_keywords\\" t-value=\\"seo_object and 'website_meta_keywords' in seo_object             and seo_object.website_meta_keywords or website_meta_keywords\\"/>\\n        <meta t-if=\\"meta_description or editable\\" name=\\"description\\" t-att-content=\\"meta_description\\"/>\\n        <meta t-if=\\"meta_keywords or editable\\" name=\\"keywords\\" t-att-content=\\"meta_keywords\\"/>\\n        <t t-if=\\"seo_object\\">\\n        <meta name=\\"default_description\\" t-att-content=\\"website_meta_description or website_meta.get('meta_description')\\" groups=\\"website.group_website_designer\\"/>\\n            <!-- OpenGraph tags for Facebook sharing -->\\n            <t t-set=\\"opengraph_meta\\" t-value=\\"website_meta.get('opengraph_meta')\\"/>\\n            <t t-if=\\"opengraph_meta\\">\\n                <t t-foreach=\\"opengraph_meta\\" t-as=\\"property\\">\\n                    <t t-if=\\"isinstance(opengraph_meta[property], list)\\">\\n                        <t t-foreach=\\"opengraph_meta[property]\\" t-as=\\"meta_content\\">\\n        <meta t-att-property=\\"property\\" t-att-content=\\"meta_content\\"/>\\n                        </t>\\n                    </t>\\n                    <t t-else=\\"\\">\\n        <meta t-att-property=\\"property\\" t-att-content=\\"opengraph_meta[property]\\"/>\\n                    </t>\\n                </t>\\n            </t>\\n            <!-- Twitter tags for sharing -->\\n            <t t-set=\\"twitter_meta\\" t-value=\\"website_meta.get('twitter_meta')\\"/>\\n            <t t-if=\\"opengraph_meta\\">\\n                <t t-foreach=\\"twitter_meta\\" t-as=\\"t_meta\\">\\n        <meta t-att-name=\\"t_meta\\" t-att-content=\\"twitter_meta[t_meta]\\"/>\\n                </t>\\n            </t>\\n        </t>\\n        <!-- `alternate`/`canonical` mainly useful to crawlers/bots/SEO tools, which test the website as public user -->\\n        <t t-if=\\"request and request.is_frontend_multilang and website and website.is_public_user()\\">\\n            <t t-set=\\"alternate_languages\\" t-value=\\"website._get_alternate_languages(canonical_params=canonical_params)\\"/>\\n            <t t-foreach=\\"alternate_languages\\" t-as=\\"lg\\">\\n        <link rel=\\"alternate\\" t-att-hreflang=\\"lg['hreflang']\\" t-att-href=\\"lg['href']\\"/>\\n            </t>\\n        </t>\\n        <link t-if=\\"request and website and website.is_public_user()\\" rel=\\"canonical\\" t-att-href=\\"website._get_canonical_url(canonical_params=canonical_params)\\"/>\\n        <!-- TODO: Once we have style in DB, add this preconnect only if a\\n        google font is actually used. Note that if no font is used, the\\n        preconnect is actually not connecting to the google servers. -->\\n        <link rel=\\"preconnect\\" href=\\"https://fonts.gstatic.com/\\" crossorigin=\\"\\"/>\\n    </xpath>\\n\\n    <xpath expr=\\"//header\\" position=\\"attributes\\">\\n        <attribute name=\\"data-name\\">Header</attribute>\\n        <attribute name=\\"t-att-data-extra-items-toggle-aria-label\\">extra_items_toggle_aria_label</attribute>\\n    </xpath>\\n\\n    <xpath expr=\\"//header/t[@t-cache]\\" position=\\"attributes\\">\\n        <!-- website.is_public_user() is needed for menus having a page with\\n        restricted visibility (only shown to logged in user): public users and\\n        logged in users can't share the menu cache. -->\\n        <attribute name=\\"t-cache\\">None if website.is_menu_cache_disabled() else (xmlid,website,website.is_public_user())</attribute>\\n    </xpath>\\n\\n    <xpath expr=\\"//header\\" position=\\"before\\">\\n        <t t-set=\\"cta_btn_text\\" t-value=\\"False\\"/>\\n        <t t-set=\\"cta_btn_href\\">/contactus</t>\\n        <t t-set=\\"extra_items_toggle_aria_label\\">Extra items button</t>\\n    </xpath>\\n\\n    <xpath expr=\\"//footer\\" position=\\"attributes\\">\\n        <attribute name=\\"data-name\\">Footer</attribute>\\n        <!-- Background now controlled by css configuration, using color combinations -->\\n        <attribute name=\\"t-attf-class\\" add=\\"o_colored_level o_cc\\" remove=\\"bg-light\\" separator=\\" \\"/>\\n        <!-- Add the main object as a cache key so that the footer_visible page\\n        option is properly reflected across pages. Controllers and other objects\\n        do not have any page option (yet) so they can share the same cache -->\\n        <attribute name=\\"t-cache\\" add=\\"website,main_object._name == 'website.page' and main_object\\"/>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('o_footer_copyright')]\\" position=\\"attributes\\">\\n        <attribute name=\\"data-name\\">Copyright</attribute>\\n        <!-- Background now controlled by css configuration, using color combinations -->\\n        <attribute name=\\"class\\" add=\\"o_colored_level o_cc\\" separator=\\" \\"/>\\n    </xpath>\\n    <xpath expr=\\"//t[@t-call='web.brand_promotion']/..\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" add=\\"o_not_editable\\" separator=\\" \\"/>\\n        <attribute name=\\"t-if\\">not editable</attribute>\\n    </xpath>\\n\\n    <xpath expr=\\"//div[@id='wrapwrap']\\" position=\\"after\\">\\n        <t t-if=\\"website and website.google_analytics_key and not editable\\">\\n            <script id=\\"tracking_code\\" t-attf-src=\\"https://www.googletagmanager.com/gtag/js?id={{ website.google_analytics_key }}\\" async=\\"async\\"/>\\n            <script id=\\"tracking_code_config\\">\\n                window.dataLayer = window.dataLayer || [];\\n                function gtag(){dataLayer.push(arguments);}\\n                gtag('consent', 'default', {\\n                    'ad_storage': 'denied',\\n                    'ad_user_data': 'denied',\\n                    'ad_personalization': 'denied',\\n                    'analytics_storage': 'denied',\\n                });\\n                gtag('js', new Date());\\n                gtag('config', '<t t-esc=\\"website.google_analytics_key\\"/>');\\n                function allConsentsGranted() {\\n                    gtag('consent', 'update', {\\n                        'ad_storage': 'granted',\\n                        'ad_user_data': 'granted',\\n                        'ad_personalization': 'granted',\\n                        'analytics_storage': 'granted',\\n                    });\\n                }\\n                <t t-if=\\"website._allConsentsGranted()\\">\\n                    allConsentsGranted();\\n                </t>\\n                <t t-else=\\"\\">\\n                    document.addEventListener(\\n                        \\"optionalCookiesAccepted\\",\\n                        allConsentsGranted,\\n                        {once: true}\\n                    );\\n                </t>\\n            </script>\\n        </t>\\n        <t t-if=\\"website and website.plausible_shared_key and not editable\\">\\n            <script id=\\"plausible_script\\" name=\\"plausible\\" defer=\\"defer\\" t-att-data-domain=\\"website.plausible_site\\" t-att-src=\\"website._get_plausible_script_url()\\"/>\\n        </t>\\n    </xpath>\\n\\n    <!-- Page options -->\\n    <xpath expr=\\"//div[@id='wrapwrap']\\" position=\\"before\\">\\n        <t groups=\\"website.group_website_restricted_editor\\">\\n            <t t-foreach=\\"['header_overlay', 'header_color', 'header_text_color', 'header_visible', 'footer_visible']\\" t-as=\\"optionName\\">\\n                <!-- Firefox autocomplete is too aggressive and works on hidden inputs,\\n                so we need to disable it (https://bugzilla.mozilla.org/show_bug.cgi?id=520561) -->\\n                <input t-if=\\"optionName in main_object\\" type=\\"hidden\\" class=\\"o_page_option_data\\" autocomplete=\\"off\\" t-att-name=\\"optionName\\" t-att-value=\\"main_object[optionName]\\"/>\\n            </t>\\n        </t>\\n\\n        <t t-set=\\"header_bg_color\\" t-value=\\"'header_color' in main_object and main_object.header_color or ''\\"/>\\n        <t t-set=\\"header_bg_color_is_class\\" t-value=\\"'bg-' in header_bg_color\\"/>\\n        <t t-set=\\"header_bg_color_class\\" t-value=\\"header_bg_color_is_class and header_bg_color or ''\\"/>\\n        <t t-set=\\"header_bg_color_style\\" t-value=\\"(not header_bg_color_is_class) and header_bg_color or ''\\"/>\\n\\n        <t t-set=\\"header_text_color\\" t-value=\\"'header_text_color' in main_object and main_object.header_text_color or ''\\"/>\\n        <t t-set=\\"header_text_color_is_class\\" t-value=\\"'text-' in header_text_color\\"/>\\n        <t t-set=\\"header_text_color_class\\" t-value=\\"header_text_color_is_class and header_text_color or ''\\"/>\\n        <t t-set=\\"header_text_color_style\\" t-value=\\"(not header_text_color_is_class) and header_text_color or ''\\"/>\\n\\n        <div groups=\\"base.group_user\\" class=\\"o_frontend_to_backend_nav position-fixed d-none\\">\\n            <svg xmlns=\\"http://www.w3.org/2000/svg\\" class=\\"o_frontend_to_backend_icon position-absolute\\" width=\\"24px\\" height=\\"24px\\" viewBox=\\"-7 -7 24 24\\" preserveAspectRatio=\\"xMinYMin\\">\\n                <path fill=\\"#FFF\\" d=\\"M8 8V1a1 1 0 1 1 2 0v8a1 1 0 0 1-1 1H1a1 1 0 1 1 0-2h7z\\"/>\\n            </svg>\\n            <div class=\\"o_frontend_to_backend_buttons d-flex\\">\\n                <a href=\\"#\\" title=\\"Go to your Odoo Apps\\" class=\\"o_frontend_to_backend_apps_btn fa fa-th d-flex align-items-center justify-content-center text-decoration-none\\" data-bs-toggle=\\"dropdown\\"/>\\n                <div class=\\"dropdown-menu o_frontend_to_backend_apps_menu\\" role=\\"menu\\">\\n                    <a role=\\"menuitem\\" class=\\"dropdown-item\\" t-esc=\\"menu['name']\\" t-as=\\"menu\\" t-foreach=\\"env['ir.ui.menu'].with_context(force_action=True).load_menus_root()['children']\\" t-attf-href=\\"/web#menu_id=#{menu['id']}&amp;action=#{menu['action'] and menu['action'].split(',')[1] or ''}\\"/>\\n                </div>\\n                <a groups=\\"website.group_website_restricted_editor\\" href=\\"#\\" title=\\"Edit this content\\" class=\\"o_frontend_to_backend_edit_btn px-3 d-flex align-items-center justify-content-center text-decoration-none\\">\\n                    <img src=\\"/website/static/description/icon.png\\" alt=\\"\\"/>Editor\\n                </a>\\n            </div>\\n        </div>\\n    </xpath>\\n    <xpath expr=\\"//div[@id='wrapwrap']\\" position=\\"attributes\\">\\n        <attribute name=\\"t-attf-class\\" add=\\"#{'o_header_overlay' if 'header_overlay' in main_object and main_object.header_overlay else ''}\\" separator=\\" \\"/>\\n    </xpath>\\n    <xpath expr=\\"//header\\" position=\\"attributes\\">\\n        <attribute name=\\"t-attf-class\\" add=\\"#{header_bg_color_class}\\" separator=\\" \\"/>\\n        <attribute name=\\"t-attf-style\\" add=\\"#{header_bg_color_style and ('background-color: %s;' % header_bg_color_style)}\\" separator=\\" \\"/>\\n        <attribute name=\\"t-attf-class\\" add=\\"#{header_text_color_class}\\" separator=\\" \\"/>\\n        <attribute name=\\"t-attf-style\\" add=\\"#{header_text_color_style and ('color: %s;' % header_text_color_style)}\\" separator=\\" \\"/>\\n    </xpath>\\n    <xpath expr=\\"//header\\" position=\\"attributes\\">\\n        <attribute name=\\"t-attf-class\\" add=\\"#{'d-none o_snippet_invisible' if 'header_visible' in main_object and not main_object.header_visible else ''}\\" separator=\\" \\"/>\\n        <attribute name=\\"t-att-data-invisible\\">'1' if 'header_visible' in main_object and not main_object.header_visible else None</attribute>\\n    </xpath>\\n    <xpath expr=\\"//footer[@id='bottom']\\" position=\\"attributes\\">\\n        <attribute name=\\"t-attf-class\\" add=\\"#{'d-none o_snippet_invisible' if 'footer_visible' in main_object and not main_object.footer_visible else ''}\\" separator=\\" \\"/>\\n        <attribute name=\\"t-att-data-invisible\\">'1' if 'footer_visible' in main_object and not main_object.footer_visible else None</attribute>\\n    </xpath>\\n</data>"}	<?xml version="1.0"?>\n<data name="Main layout" inherit_id="portal.frontend_layout">\n    <xpath expr="//html" position="before">\n        <t t-set="html_data" t-value="{             'lang': lang and lang.replace('_', '-'),             'data-website-id': website.id if website else None,             'data-edit_translations': '1' if edit_translations else None,             'data-main-object': repr(main_object) if main_object else None,             'data-seo-object': repr(seo_object) if seo_object else None,         }"/>\n        <t t-if="not request.env.user._is_public()" t-set="nothing" t-value="html_data.update({             'data-is-published': 'website_published' in main_object.fields_get() and main_object.website_published,             'data-can-optimize-seo': 'website_meta_description' in main_object.fields_get(),             'data-can-publish': 'can_publish' in main_object.fields_get() and main_object.can_publish,             'data-editable-in-backend': edit_in_backend or ('website_published' in main_object.fields_get() and main_object._name != 'website.page'),         })"/>\n        <!--\n        TODO Review in master (this is a stable fix for new databases).\n        See REVIEW_CAN_PUBLISH_UNSUDO.\n        -->\n        <t t-if="html_data and html_data.get('data-can-publish') == True">\n            <t t-set="nothing" t-value="html_data.update({                 'data-can-publish': 'can_publish' in main_object.fields_get() and main_object.sudo(flag=False).can_publish,             })"/>\n        </t>\n        <t t-if="editable or translatable" t-set="nothing" t-value="html_data.update({             'data-editable': '1' if editable else None,             'data-translatable': '1' if translatable else None,             'data-view-xmlid': xmlid,             'data-viewid': viewid,         })"/>\n    </xpath>\n\n    <xpath expr="//head" position="attributes">\n        <!--\n        Cache the <head> of the website.layout:\n        - For each individual website.page record (their css/js might be the\n          same but their title will not for example). Arguably we could do this\n          for any record (not only website.page) but this t-cache was originally\n          added to replace the website.page own cache system. For other records,\n          it could probably depend on each individual access right.\n        - Only for non-designers (especially visitors) (hence the "editable or\n          translatable" check).\n        - Only if not in any debug mode (we want any correct value of debug mode\n          to correctly appear in the `odoo` object + assets may depend on this\n          (e.g. debug=assets or debug=tests)).\n        -->\n        <attribute name="t-cache">main_object if main_object and main_object._name == 'website.page' and not request.session.debug and not editable and not translatable else None</attribute>\n    </xpath>\n    <xpath expr="//head/*[1]" position="before">\n        <t t-if="not title">\n            <t t-if="not additional_title and main_object and 'name' in main_object">\n                <t t-set="additional_title" t-value="main_object.name"/>\n            </t>\n            <t t-set="default_title" t-translation="off" t-value="(additional_title + ' | ' if additional_title else '') + (website or res_company).name"/>\n            <t t-set="seo_object" t-value="seo_object or main_object"/>\n            <t t-if="seo_object and 'website_meta_title' in seo_object and seo_object.website_meta_title">\n                <t t-set="title" t-value="seo_object.website_meta_title"/>\n            </t>\n            <t t-else="">\n                <t t-set="title" t-value="default_title"/>\n            </t>\n        </t>\n        <t t-set="x_icon" t-value="website.image_url(website, 'favicon')"/>\n    </xpath>\n    <xpath expr="//head/meta[last()]" position="after">\n        <meta name="generator" content="Odoo"/>\n        <t t-set="website_meta" t-value="seo_object and seo_object.get_website_meta() or {}"/>\n        <meta name="default_title" t-att-content="default_title" groups="website.group_website_designer"/>\n        <meta t-if="(main_object and 'website_indexed' in main_object         and not main_object.website_indexed) or (website.domain and not website._is_indexable_url(request.httprequest.url_root))" name="robots" content="noindex"/>\n        <t t-set="seo_object" t-value="seo_object or main_object"/>\n        <t t-set="meta_description" t-value="seo_object and 'website_meta_description' in seo_object             and seo_object.website_meta_description or website_meta_description or website_meta.get('meta_description', '')"/>\n        <t t-set="meta_keywords" t-value="seo_object and 'website_meta_keywords' in seo_object             and seo_object.website_meta_keywords or website_meta_keywords"/>\n        <meta t-if="meta_description or editable" name="description" t-att-content="meta_description"/>\n        <meta t-if="meta_keywords or editable" name="keywords" t-att-content="meta_keywords"/>\n        <t t-if="seo_object">\n        <meta name="default_description" t-att-content="website_meta_description or website_meta.get('meta_description')" groups="website.group_website_designer"/>\n            <!-- OpenGraph tags for Facebook sharing -->\n            <t t-set="opengraph_meta" t-value="website_meta.get('opengraph_meta')"/>\n            <t t-if="opengraph_meta">\n                <t t-foreach="opengraph_meta" t-as="property">\n                    <t t-if="isinstance(opengraph_meta[property], list)">\n                        <t t-foreach="opengraph_meta[property]" t-as="meta_content">\n        <meta t-att-property="property" t-att-content="meta_content"/>\n                        </t>\n                    </t>\n                    <t t-else="">\n        <meta t-att-property="property" t-att-content="opengraph_meta[property]"/>\n                    </t>\n                </t>\n            </t>\n            <!-- Twitter tags for sharing -->\n            <t t-set="twitter_meta" t-value="website_meta.get('twitter_meta')"/>\n            <t t-if="opengraph_meta">\n                <t t-foreach="twitter_meta" t-as="t_meta">\n        <meta t-att-name="t_meta" t-att-content="twitter_meta[t_meta]"/>\n                </t>\n            </t>\n        </t>\n        <!-- `alternate`/`canonical` mainly useful to crawlers/bots/SEO tools, which test the website as public user -->\n        <t t-if="request and request.is_frontend_multilang and website and website.is_public_user()">\n            <t t-set="alternate_languages" t-value="website._get_alternate_languages(canonical_params=canonical_params)"/>\n            <t t-foreach="alternate_languages" t-as="lg">\n        <link rel="alternate" t-att-hreflang="lg['hreflang']" t-att-href="lg['href']"/>\n            </t>\n        </t>\n        <link t-if="request and website and website.is_public_user()" rel="canonical" t-att-href="website._get_canonical_url(canonical_params=canonical_params)"/>\n        <!-- TODO: Once we have style in DB, add this preconnect only if a\n        google font is actually used. Note that if no font is used, the\n        preconnect is actually not connecting to the google servers. -->\n        <link rel="preconnect" href="https://fonts.gstatic.com/" crossorigin=""/>\n    </xpath>\n\n    <xpath expr="//header" position="attributes">\n        <attribute name="data-name">Header</attribute>\n        <attribute name="t-att-data-extra-items-toggle-aria-label">extra_items_toggle_aria_label</attribute>\n    </xpath>\n\n    <xpath expr="//header/t[@t-cache]" position="attributes">\n        <!-- website.is_public_user() is needed for menus having a page with\n        restricted visibility (only shown to logged in user): public users and\n        logged in users can't share the menu cache. -->\n        <attribute name="t-cache">None if website.is_menu_cache_disabled() else (xmlid,website,website.is_public_user())</attribute>\n    </xpath>\n\n    <xpath expr="//header" position="before">\n        <t t-set="cta_btn_text" t-value="False"/>\n        <t t-set="cta_btn_href">/contactus</t>\n        <t t-set="extra_items_toggle_aria_label">Extra items button</t>\n    </xpath>\n\n    <xpath expr="//footer" position="attributes">\n        <attribute name="data-name">Footer</attribute>\n        <!-- Background now controlled by css configuration, using color combinations -->\n        <attribute name="t-attf-class" add="o_colored_level o_cc" remove="bg-light" separator=" "/>\n        <!-- Add the main object as a cache key so that the footer_visible page\n        option is properly reflected across pages. Controllers and other objects\n        do not have any page option (yet) so they can share the same cache -->\n        <attribute name="t-cache" add="website,main_object._name == 'website.page' and main_object"/>\n    </xpath>\n    <xpath expr="//div[hasclass('o_footer_copyright')]" position="attributes">\n        <attribute name="data-name">Copyright</attribute>\n        <!-- Background now controlled by css configuration, using color combinations -->\n        <attribute name="class" add="o_colored_level o_cc" separator=" "/>\n    </xpath>\n    <xpath expr="//t[@t-call='web.brand_promotion']/.." position="attributes">\n        <attribute name="class" add="o_not_editable" separator=" "/>\n        <attribute name="t-if">not editable</attribute>\n    </xpath>\n\n    <xpath expr="//div[@id='wrapwrap']" position="after">\n        <t t-if="website and website.google_analytics_key and not editable">\n            <script id="tracking_code" t-attf-src="https://www.googletagmanager.com/gtag/js?id={{ website.google_analytics_key }}" async="async"/>\n            <script id="tracking_code_config">\n                window.dataLayer = window.dataLayer || [];\n                function gtag(){dataLayer.push(arguments);}\n                gtag('consent', 'default', {\n                    'ad_storage': 'denied',\n                    'ad_user_data': 'denied',\n                    'ad_personalization': 'denied',\n                    'analytics_storage': 'denied',\n                });\n                gtag('js', new Date());\n                gtag('config', '<t t-esc="website.google_analytics_key"/>');\n                function allConsentsGranted() {\n                    gtag('consent', 'update', {\n                        'ad_storage': 'granted',\n                        'ad_user_data': 'granted',\n                        'ad_personalization': 'granted',\n                        'analytics_storage': 'granted',\n                    });\n                }\n                <t t-if="website._allConsentsGranted()">\n                    allConsentsGranted();\n                </t>\n                <t t-else="">\n                    document.addEventListener(\n                        "optionalCookiesAccepted",\n                        allConsentsGranted,\n                        {once: true}\n                    );\n                </t>\n            </script>\n        </t>\n        <t t-if="website and website.plausible_shared_key and not editable">\n            <script id="plausible_script" name="plausible" defer="defer" t-att-data-domain="website.plausible_site" t-att-src="website._get_plausible_script_url()"/>\n        </t>\n    </xpath>\n\n    <!-- Page options -->\n    <xpath expr="//div[@id='wrapwrap']" position="before">\n        <t groups="website.group_website_restricted_editor">\n            <t t-foreach="['header_overlay', 'header_color', 'header_text_color', 'header_visible', 'footer_visible']" t-as="optionName">\n                <!-- Firefox autocomplete is too aggressive and works on hidden inputs,\n                so we need to disable it (https://bugzilla.mozilla.org/show_bug.cgi?id=520561) -->\n                <input t-if="optionName in main_object" type="hidden" class="o_page_option_data" autocomplete="off" t-att-name="optionName" t-att-value="main_object[optionName]"/>\n            </t>\n        </t>\n\n        <t t-set="header_bg_color" t-value="'header_color' in main_object and main_object.header_color or ''"/>\n        <t t-set="header_bg_color_is_class" t-value="'bg-' in header_bg_color"/>\n        <t t-set="header_bg_color_class" t-value="header_bg_color_is_class and header_bg_color or ''"/>\n        <t t-set="header_bg_color_style" t-value="(not header_bg_color_is_class) and header_bg_color or ''"/>\n\n        <t t-set="header_text_color" t-value="'header_text_color' in main_object and main_object.header_text_color or ''"/>\n        <t t-set="header_text_color_is_class" t-value="'text-' in header_text_color"/>\n        <t t-set="header_text_color_class" t-value="header_text_color_is_class and header_text_color or ''"/>\n        <t t-set="header_text_color_style" t-value="(not header_text_color_is_class) and header_text_color or ''"/>\n\n        <div groups="base.group_user" class="o_frontend_to_backend_nav position-fixed d-none">\n            <svg xmlns="http://www.w3.org/2000/svg" class="o_frontend_to_backend_icon position-absolute" width="24px" height="24px" viewBox="-7 -7 24 24" preserveAspectRatio="xMinYMin">\n                <path fill="#FFF" d="M8 8V1a1 1 0 1 1 2 0v8a1 1 0 0 1-1 1H1a1 1 0 1 1 0-2h7z"/>\n            </svg>\n            <div class="o_frontend_to_backend_buttons d-flex">\n                <a href="#" title="Go to your Odoo Apps" class="o_frontend_to_backend_apps_btn fa fa-th d-flex align-items-center justify-content-center text-decoration-none" data-bs-toggle="dropdown"/>\n                <div class="dropdown-menu o_frontend_to_backend_apps_menu" role="menu">\n                    <a role="menuitem" class="dropdown-item" t-esc="menu['name']" t-as="menu" t-foreach="env['ir.ui.menu'].with_context(force_action=True).load_menus_root()['children']" t-attf-href="/web#menu_id=#{menu['id']}&amp;action=#{menu['action'] and menu['action'].split(',')[1] or ''}"/>\n                </div>\n                <a groups="website.group_website_restricted_editor" href="#" title="Edit this content" class="o_frontend_to_backend_edit_btn px-3 d-flex align-items-center justify-content-center text-decoration-none">\n                    <img src="/website/static/description/icon.png" alt=""/>Editor\n                </a>\n            </div>\n        </div>\n    </xpath>\n    <xpath expr="//div[@id='wrapwrap']" position="attributes">\n        <attribute name="t-attf-class" add="#{'o_header_overlay' if 'header_overlay' in main_object and main_object.header_overlay else ''}" separator=" "/>\n    </xpath>\n    <xpath expr="//header" position="attributes">\n        <attribute name="t-attf-class" add="#{header_bg_color_class}" separator=" "/>\n        <attribute name="t-attf-style" add="#{header_bg_color_style and ('background-color: %s;' % header_bg_color_style)}" separator=" "/>\n        <attribute name="t-attf-class" add="#{header_text_color_class}" separator=" "/>\n        <attribute name="t-attf-style" add="#{header_text_color_style and ('color: %s;' % header_text_color_style)}" separator=" "/>\n    </xpath>\n    <xpath expr="//header" position="attributes">\n        <attribute name="t-attf-class" add="#{'d-none o_snippet_invisible' if 'header_visible' in main_object and not main_object.header_visible else ''}" separator=" "/>\n        <attribute name="t-att-data-invisible">'1' if 'header_visible' in main_object and not main_object.header_visible else None</attribute>\n    </xpath>\n    <xpath expr="//footer[@id='bottom']" position="attributes">\n        <attribute name="t-attf-class" add="#{'d-none o_snippet_invisible' if 'footer_visible' in main_object and not main_object.footer_visible else ''}" separator=" "/>\n        <attribute name="t-att-data-invisible">'1' if 'footer_visible' in main_object and not main_object.footer_visible else None</attribute>\n    </xpath>\n</data>\n\n	f	t	2026-04-14 18:11:46.315853	2026-04-14 18:11:46.315853	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
