ut=\\"step[1]['name']\\"/>\\n                        </p>\\n                        <span t-if=\\"not step_last\\" class=\\"fa fa-angle-right d-inline-block align-middle mx-sm-3 text-muted fs-5\\"/>\\n                    </div>\\n                </a>\\n            </t>\\n            <!-- Mobile screen views -->\\n            <div class=\\"d-flex d-md-none flex-column align-items-start\\">\\n                <div class=\\"dropdown\\">\\n                    <a class=\\"dropdown-toggle fw-bold\\" role=\\"button\\" data-bs-toggle=\\"dropdown\\" aria-expanded=\\"false\\" title=\\"Steps\\">\\n                        <t t-out=\\"list(filter(lambda step: xmlid in step[0],wizard_step))[0][1]['name']\\"/>\\n                    </a>\\n                    <ul class=\\"dropdown-menu\\">\\n                        <t t-set=\\"current_step\\" t-value=\\"None\\"/>\\n                        <li t-foreach=\\"wizard_step\\" t-as=\\"step\\">\\n                            <t t-set=\\"is_current_step\\" t-value=\\"xmlid in step[0]\\"/>\\n                            <t t-if=\\"is_current_step\\">\\n                                <t t-set=\\"current_step\\" t-value=\\"step\\"/>\\n                                <t t-set=\\"_steps_in_deg\\" t-value=\\"(step_index + 1) / len(wizard_step) * 360\\"/>\\n                                <t t-set=\\"next_step\\" t-value=\\"wizard_step[step_index+1] if step_index+1 &lt; len(wizard_step) else False\\"/>\\n                            </t>\\n                            <a t-if=\\"not current_step\\" class=\\"dropdown-item\\" t-att-href=\\"step[1]['current_href']\\" t-out=\\"step[1]['name']\\" t-att-title=\\"step[1]['name']\\"/>\\n                            <span t-else=\\"\\" t-attf-class=\\"dropdown-item {{'fw-bold' if is_current_step else 'text-muted o_disabled'}}\\" t-out=\\"step[1]['name']\\" t-att-title=\\"step[1]['name']\\"/>\\n                        </li>\\n                    </ul>\\n                </div>\\n                <span t-if=\\"next_step\\" class=\\"d-inline-block d-md-none text-muted\\">\\n                        Next: <t t-out=\\"next_step[1]['name']\\"/>\\n                </span>\\n            </div>\\n        </div>\\n        <div class=\\"o_wizard_circle_progress progress d-md-none position-relative rounded-circle ms-3 bg-transparent\\" t-attf-style=\\"--rightProgress:{{'180' if _steps_in_deg &gt;= 180 else _steps_in_deg}}deg; --leftProgress:{{_steps_in_deg-180 if _steps_in_deg &gt;= 180 else 0}}deg;\\">\\n            <span class=\\"o_wizard_circle_progress_left position-absolute start-0 top-0 z-index-1 overflow-hidden w-50 h-100 \\">\\n                <span class=\\"progress-bar position-absolute start-100 top-0 w-100 h-100 border border-5 border-start-0 border-primary bg-transparent\\"/>\\n            </span>\\n            <span class=\\"o_wizard_circle_progress_right position-absolute top-0 end-0 z-index-1 overflow-hidden w-50 h-100\\">\\n                <span class=\\"progress-bar position-absolute top-0 end-100 w-100 h-100 border border-5 border-end-0 border-primary bg-transparent\\"/>\\n            </span>\\n            <p class=\\"mx-auto fw-bold\\">\\n                <t t-out=\\"wizard_step.index(current_step)+1\\"/>\\n                of\\n                <t t-out=\\"len(wizard_step)\\"/>\\n            </p>\\n        </div>\\n    </div>\\n</t>"}	<?xml version="1.0"?>\n<t name="Step Checkout" t-name="website.step_wizard">\n    <!-- parameters:\n        - wizard_step: An ordered list of steps. Each step must contain:\n                       - (1): A list of the xmlid of the templates for which the step applies for\n                       - (2): A dict that must contain the following keys: ['name', 'current_href']\n    -->\n    <div class="o_wizard d-flex flex-wrap justify-content-between justify-content-md-start my-3 my-sm-4">\n        <div class="d-flex flex-column flex-md-row align-items-end align-items-md-start justify-content-center">\n            <!-- Large screen views -->\n            <t t-foreach="wizard_step" t-as="step">\n                <t t-set="is_current_step" t-value="xmlid in step[0]"/>\n                <t t-if="is_current_step" t-set="current_step" t-value="step"/>\n                <span t-if="current_step" t-attf-class="#{not is_current_step and 'o_disabled'} d-none d-md-flex no-decoration">\n                    <div t-attf-class="d-flex align-items-center {{'o_wizard_step_active fw-bold' if is_current_step else 'text-muted'}}">\n                        <p class="o_wizard_steplabel text-center mb-0">\n                            <t t-out="step[1]['name']"/>\n                        </p>\n                        <span t-if="not step_last" class="fa fa-angle-right d-inline-block align-middle mx-sm-3 text-muted fs-5"/>\n                    </div>\n                </span>\n                <a t-else="" class="d-none d-md-flex no-decoration" t-att-href="step[1]['current_href']" t-att-title="step[1]['name']">\n                    <div class="d-flex align-items-center o_wizard_step-done">\n                        <p class="o_wizard_steplabel text-center mb-0">\n                            <t t-out="step[1]['name']"/>\n                        </p>\n                        <span t-if="not step_last" class="fa fa-angle-right d-inline-block align-middle mx-sm-3 text-muted fs-5"/>\n                    </div>\n                </a>\n            </t>\n            <!-- Mobile screen views -->\n            <div class="d-flex d-md-none flex-column align-items-start">\n                <div class="dropdown">\n                    <a class="dropdown-toggle fw-bold" role="button" data-bs-toggle="dropdown" aria-expanded="false" title="Steps">\n                        <t t-out="list(filter(lambda step: xmlid in step[0],wizard_step))[0][1]['name']"/>\n                    </a>\n                    <ul class="dropdown-menu">\n                        <t t-set="current_step" t-value="None"/>\n                        <li t-foreach="wizard_step" t-as="step">\n                            <t t-set="is_current_step" t-value="xmlid in step[0]"/>\n                            <t t-if="is_current_step">\n                                <t t-set="current_step" t-value="step"/>\n                                <t t-set="_steps_in_deg" t-value="(step_index + 1) / len(wizard_step) * 360"/>\n                                <t t-set="next_step" t-value="wizard_step[step_index+1] if step_index+1 &lt; len(wizard_step) else False"/>\n                            </t>\n                            <a t-if="not current_step" class="dropdown-item" t-att-href="step[1]['current_href']" t-out="step[1]['name']" t-att-title="step[1]['name']"/>\n                            <span t-else="" t-attf-class="dropdown-item {{'fw-bold' if is_current_step else 'text-muted o_disabled'}}" t-out="step[1]['name']" t-att-title="step[1]['name']"/>\n                        </li>\n                    </ul>\n                </div>\n                <span t-if="next_step" class="d-inline-block d-md-none text-muted">\n                        Next: <t t-out="next_step[1]['name']"/>\n                </span>\n            </div>\n        </div>\n        <div class="o_wizard_circle_progress progress d-md-none position-relative rounded-circle ms-3 bg-transparent" t-attf-style="--rightProgress:{{'180' if _steps_in_deg &gt;= 180 else _steps_in_deg}}deg; --leftProgress:{{_steps_in_deg-180 if _steps_in_deg &gt;= 180 else 0}}deg;">\n            <span class="o_wizard_circle_progress_left position-absolute start-0 top-0 z-index-1 overflow-hidden w-50 h-100 ">\n                <span class="progress-bar position-absolute start-100 top-0 w-100 h-100 border border-5 border-start-0 border-primary bg-transparent"/>\n            </span>\n            <span class="o_wizard_circle_progress_right position-absolute top-0 end-0 z-index-1 overflow-hidden w-50 h-100">\n                <span class="progress-bar position-absolute top-0 end-100 w-100 h-100 border border-5 border-end-0 border-primary bg-transparent"/>\n            </span>\n            <p class="mx-auto fw-bold">\n                <t t-out="wizard_step.index(current_step)+1"/>\n                of\n                <t t-out="len(wizard_step)"/>\n            </p>\n        </div>\n    </div>\n</t>\n\n	f	t	2026-04-14 18:11:46.315853	2026-04-14 18:11:46.315853	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
