-class=\\"o_anim_zoom_out\\" data-trigger=\\"animation_direction_in_place_opt\\">Zoom Out</we-button>\\n            <we-button data-select-class=\\"o_anim_zoom_in\\" data-trigger=\\"animation_direction_in_place_opt\\">Zoom In</we-button>\\n            <we-button data-select-class=\\"o_anim_flash\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Flash</we-button>\\n            <we-button data-select-class=\\"o_anim_pulse\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Pulse</we-button>\\n            <we-button data-select-class=\\"o_anim_shake\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Shake</we-button>\\n            <we-button data-select-class=\\"o_anim_tada\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Tada</we-button>\\n            <we-button data-select-class=\\"o_anim_flip_in_x\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Flip-In-X</we-button>\\n            <we-button data-select-class=\\"o_anim_flip_in_y\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Flip-In-Y</we-button>\\n        </we-select>\\n        <!-- Direction -->\\n        <we-select string=\\"Direction\\" class=\\"o_we_sublevel_1\\" data-name=\\"animation_direction_opt\\" data-force-animation=\\"true\\">\\n            <we-button data-select-class=\\"\\" data-name=\\"animation_direction_in_place_opt\\" data-dependencies=\\"!o_anim_slide_in_opt\\">In Place</we-button>\\n            <we-button data-select-class=\\"o_anim_from_right\\" data-name=\\"animation_direction_from_right_opt\\" data-dependencies=\\"!o_anim_rotate_opt\\">From Right</we-button>\\n            <we-button data-select-class=\\"o_anim_from_left\\" data-dependencies=\\"!o_anim_rotate_opt\\">From Left</we-button>\\n            <we-button data-select-class=\\"o_anim_from_bottom\\" data-dependencies=\\"!o_anim_rotate_opt\\">From Bottom</we-button>\\n            <we-button data-select-class=\\"o_anim_from_top\\" data-dependencies=\\"!o_anim_rotate_opt\\">From Top</we-button>\\n            <we-button data-select-class=\\"o_anim_from_top_right\\" data-dependencies=\\"o_anim_rotate_opt\\">From Top Right</we-button>\\n            <we-button data-select-class=\\"o_anim_from_top_left\\" data-dependencies=\\"o_anim_rotate_opt\\">From Top Left</we-button>\\n            <we-button data-select-class=\\"o_anim_from_bottom_right\\" data-dependencies=\\"o_anim_rotate_opt\\">From Bottom Right</we-button>\\n            <we-button data-select-class=\\"o_anim_from_bottom_left\\" data-dependencies=\\"o_anim_rotate_opt\\">From Bottom Left</we-button>\\n        </we-select>\\n        <!-- Trigger -->\\n        <we-select string=\\"Trigger\\" class=\\"o_we_sublevel_1\\" data-dependencies=\\"animation_on_appearance_opt\\" data-name=\\"animation_trigger_opt\\">\\n            <we-button data-select-class=\\"\\">First Time Only</we-button>\\n            <we-button data-select-class=\\"o_animate_both_scroll\\">Every Time</we-button>\\n        </we-select>\\n        <!-- Intensity -->\\n        <we-range string=\\"Intensity\\" class=\\"o_we_sublevel_1\\" data-name=\\"animation_intensity_opt\\" data-animation-intensity=\\"\\" data-min=\\"1\\" data-max=\\"100\\" data-step=\\"1\\" data-display-range-value=\\"true\\" data-no-preview=\\"true\\"/>\\n        <!-- Scroll Zone -->\\n        <we-row string=\\"Scroll Zone\\" class=\\"o_we_sublevel_1\\">\\n            <we-input data-unit=\\"%\\" data-step=\\"1\\" data-dependencies=\\"animation_on_scroll_opt\\" data-no-preview=\\"true\\" data-select-data-attribute=\\"\\" data-attribute-name=\\"scrollZoneStart\\" data-force-animation=\\"true\\"/>\\n            <span class=\\"mx-2\\">to</span>\\n            <we-input data-unit=\\"%\\" data-step=\\"1\\" data-dependencies=\\"animation_on_scroll_opt\\" data-no-preview=\\"true\\" data-select-data-attribute=\\"\\" data-attribute-name=\\"scrollZoneEnd\\" data-force-animation=\\"true\\"/>\\n        </we-row>\\n        <!-- Start After -->\\n        <we-input string=\\"Start After\\" class=\\"o_we_sublevel_1 o_we_small_input\\" data-dependencies=\\"animation_on_appearance_opt\\" data-name=\\"animation_delay_opt\\" data-select-style=\\"0s\\" data-css-property=\\"animation-delay\\" data-unit=\\"s\\"/>\\n        <!-- Duration -->\\n        <we-input string=\\"Duration\\" class=\\"o_we_sublevel_1 o_we_small_input\\" data-dependencies=\\"animation_on_appearance_opt\\" data-select-style=\\"0.4s\\" data-css-property=\\"animation-duration\\" data-unit=\\"s\\"/>\\n    </div>\\n\\n    <!-- Text highlight effects -->\\n    <div data-js=\\"TextHighlight\\" data-selector=\\".o_text_highlight\\">\\n        <!-- Text highlight style -->\\n        <we-select string=\\"Highlight\\" data-name=\\"text_highlight_opt\\" class=\\"o_we_select_grid\\">\\n            <div class=\\"grid gap-0\\">\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_underline\\" data-set-text-highlight=\\"underline\\" data-select-label=\\"Underline\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_freehand_1\\" data-set-text-highlight=\\"freehand_1\\" data-select-label=\\"Freehand 1\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_freehand_2 o_text_highlight_fill\\" data-set-text-highlight=\\"freehand_2\\" data-select-label=\\"Freehand 2\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_freehand_3 o_text_highlight_fill\\" data-set-text-highlight=\\"freehand_3\\" data-select-label=\\"Freehand 3\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_double\\" data-set-text-highlight=\\"double\\" data-select-label=\\"Double\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_wavy\\" data-set-text-highlight=\\"wavy\\" data-select-label=\\"Wavy\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_circle_1\\" data-set-text-highlight=\\"circle_1\\" data-select-label=\\"Circle 1\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_circle_2 o_text_highlight_fill\\" data-set-text-highlight=\\"circle_2\\" data-select-label=\\"Circle 2\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_circle_3 o_text_highlight_fill\\" data-set-text-highlight=\\"circle_3\\" data-select-label=\\"Circle 3\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_over_underline\\" data-set-text-highlight=\\"over_underline\\" data-select-label=\\"Over And Underline\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_scribble_1\\" data-set-text-highlight=\\"scribble_1\\" data-select-label=\\"Scribble 1\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_scribble_2 o_text_highlight_fill\\" data-set-text-highlight=\\"scribble_2\\" data-select-label=\\"Scribble 2\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_scribble_3 o_text_highlight_fill\\" data-set-text-highlight=\\"scribble_3\\" data-select-label=\\"Scribble 3\\"/>\\n                <we-button class=\\"g-col-4 text-black-50\\" data-select-class=\\"o_text_highlight_scribble_4 o_text_highlight_fill\\" data-set-text-highlight=\\"scribble_4\\" data-select-label=\\"Scribble 4\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_jagged\\" data-set-text-highlight=\\"jagged\\" data-select-label=\\"Jagged\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_cross\\" data-set-text-highlight=\\"cross\\" data-select-label=\\"Cross\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_diagonal\\" data-set-text-highlight=\\"diagonal\\" data-select-label=\\"Diagonal\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_strikethrough\\" data-set-text-highlight=\\"strikethrough\\" data-select-label=\\"Strikethrough\\"/>\\n                <we-button class=\\"g-col-4 text-black-50\\" data-select-class=\\"o_text_highlight_bold o_text_highlight_fill\\" data-set-text-highlight=\\"bold\\" data-select-label=\\"Bold\\"/>\\n                <we-button class=\\"g-col-4 text-black-50\\" data-select-class=\\"o_text_highlight_bold_1 o_text_highlight_fill\\" data-set-text-highlight=\\"bold_1\\" data-select-label=\\"Bold 1\\"/>\\n                <we-button class=\\"g-col-4 text-black-50\\" data-select-class=\\"o_text_highlight_bold_2 o_text_highlight_fill\\" data-set-text-highlight=\\"bold_2\\" data-select-label=\\"Bold 2\\"/>\\n            </div>\\n        </we-select>\\n        <!-- Text highlight color -->\\n        <we-colorpicker string=\\"Color\\" class=\\"o_we_sublevel_1\\" data-dependencies=\\"text_highlight_opt\\" data-css-property=\\"--text-highlight-color\\" data-select-style=\\"\\"/>\\n        <!-- Text highlight thickness -->\\n        <we-input string=\\"Thickness\\" class=\\"o_we_sublevel_1 o_we_small_input\\" data-dependencies=\\"text_highlight_opt\\" data-css-property=\\"--text-highlight-width\\" data-select-style=\\"\\" data-unit=\\"px\\"/>\\n    </div>\\n\\n    <!-- Theme options -->\\n    <div data-js=\\"ThemeColors\\" data-selector=\\"theme-colors\\" data-no-check=\\"true\\">\\n        <we-alert class=\\"o_old_color_system_warning d-none mt-2\\">\\n            It appears your website is still using the old color system of\\n            Odoo 13.0 in some places. We made sure it is still working but\\n            we recommend you to try to use the new color system, which is\\n            still customizable.\\n        </we-alert>\\n        <we-row class=\\"o_we_theme_colors_selector\\">\\n            <div class=\\"o_we_theme_colors_selector_group\\">\\n                <we-title>Main</we-title>\\n                <we-colorpicker data-name=\\"color_1_opt\\" title=\\"Primary\\" data-customize-website-color=\\"\\" data-color=\\"o-color-1\\" data-use-css-color=\\"true\\" data-selected-tab=\\"custom-colors\\"/>\\n                <we-colorpicker data-name=\\"color_2_opt\\" title=\\"Secondary\\" data-customize-website-color=\\"\\" data-color=\\"o-color-2\\" data-use-css-color=\\"true\\" data-selected-tab=\\"custom-colors\\"/>\\n            </div>\\n            <div class=\\"o_we_theme_colors_selector_group\\">\\n                <we-title>Light &amp; Dark</we-title>\\n                <we-colorpicker data-customize-website-color=\\"\\" data-color=\\"o-color-3\\" data-use-css-color=\\"true\\" data-selected-tab=\\"custom-colors\\"/>\\n                <we-colorpicker data-customize-website-color=\\"\\" data-color=\\"o-color-4\\" data-use-css-color=\\"true\\" data-selected-tab=\\"custom-colors\\"/>\\n                <we-colorpicker data-customize-website-color=\\"\\" data-color=\\"o-color-5\\" data-use-css-color=\\"true\\" data-selected-tab=\\"custom-colors\\"/>\\n            </div>\\n            <we-select data-img=\\"/website/static/src/img/snippets_options/palette.svg\\" class=\\"o_we_theme_colors_select\\" data-variable=\\"color-palettes-name\\"/>\\n        </we-row>\\n        <we-collapse class=\\"o_we_theme_presets_collapse\\" string=\\"Color Presets\\">\\n        </we-collapse>\\n    </div>\\n    <div data-js=\\"OptionsTab\\" data-selector=\\"website-settings\\" data-no-check=\\"true\\">\\n        <we-row string=\\"Theme\\" groups=\\"base.group_system\\">\\n            <we-button data-switch-theme=\\"\\" data-no-preview=\\"true\\" class=\\"o_we_bg_brand_primary\\">Switch Theme</we-button>\\n        </we-row>\\n        <we-row string=\\"Language\\">\\n            <we-button data-add-language=\\"\\" data-no-preview=\\"true\\" class=\\"o_we_bg_brand_primary\\">Add a Language</we-button>\\n        </we-row>\\n        <we-select string=\\"Page Layout\\" data-variable=\\"layout\\">\\n            <we-button data-customize-website-variable=\\"'full'\\" data-name=\\"layout_full_opt\\">Full</we-button>\\n            <we-button data-customize-website-variable=\\"'boxed'\\">Boxed</we-button>\\n            <we-button data-customize-website-variable=\\"'framed'\\">Framed</we-button>\\n            <we-button data-customize-website-variable=\\"'postcard'\\">Postcard</we-button>\\n        </we-select>\\n        <we-row string=\\"Background\\" class=\\"o_we_sublevel_1\\" data-no-preview=\\"true\\">\\n            <we-colorpicker data-dependencies=\\"!layout_full_opt\\" data-customize-website-color=\\"\\" data-color=\\"body\\"/>\\n            <we-button-group data-imagepicker=\\"body_bg_image_opt\\">\\n                <we-button title=\\"Image\\" class=\\"fa fa-fw fa-camera\\" data-customize-body-bg-type=\\"'image'\\"/>\\n                <we-button title=\\"Pattern\\" class=\\"fa fa-fw fa-th\\" data-customize-body-bg-type=\\"'pattern'\\"/>\\n                <we-button title=\\"None\\" class=\\"fa fa-fw fa-ban\\" data-customize-body-bg-type=\\"NONE\\"/>\\n            </we-button-group>\\n            <!-- Hidden imagepicker enabled by above button-group -->\\n            <we-imagepicker data-name=\\"body_bg_image_opt\\" data-customize-body-bg=\\"\\"/>\\n        </we-row>\\n    </div>\\n    <div data-js=\\"OptionsTab\\" data-selector=\\"theme-paragraph\\" data-no-check=\\"true\\">\\n        <we-collapse>\\n            <we-input string=\\"Font size\\" data-customize-website-variable=\\"null\\" data-variable=\\"font-size-base\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Small\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"null\\" data-variable=\\"small-font-size\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n        </we-collapse>\\n        <we-fontfamilypicker string=\\"Font family\\" data-variable=\\"font\\"/>\\n        <!-- \\"× \\": \\\\u00D7\\\\u2000 -->\\n        <we-input string=\\"Line height\\" data-customize-website-variable=\\"null\\" data-variable=\\"body-line-height\\" data-fake-unit=\\"× \\"/>\\n        <we-row string=\\"Margins\\">\\n            <we-input title=\\"Top\\" data-customize-website-variable=\\"\\" data-variable=\\"paragraph-margin-top\\" data-unit=\\"px\\" data-save-unit=\\"px\\"/>\\n            <we-input title=\\"Bottom\\" data-customize-website-variable=\\"\\" data-variable=\\"paragraph-margin-bottom\\" data-unit=\\"px\\" data-save-unit=\\"px\\"/>\\n        </we-row>\\n    </div>\\n    <div data-js=\\"OptionsTab\\" data-selector=\\"theme-headings\\" data-no-check=\\"true\\">\\n        <t t-set=\\"heading_label\\">Heading</t>\\n        <t t-set=\\"display_label\\">Display</t>\\n        <we-collapse>\\n            <we-input string=\\"Font size\\" title=\\"Heading 1\\" data-customize-website-variable=\\"null\\" data-variable=\\"h1-font-size\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <t t-foreach=\\"[2, 3, 4, 5, 6]\\" t-as=\\"depth\\">\\n                <we-input t-attf-string=\\"#{heading_label} #{depth}\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"null\\" t-attf-data-variable=\\"h#{depth}-font-size\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            </t>\\n            <!-- We don't use `display-font-sizes.5` and `display-font-sizes.6` -->\\n            <t t-set=\\"used_display_font_sizes\\" t-value=\\"[1, 2, 3, 4]\\"/>\\n            <t t-foreach=\\"used_display_font_sizes\\" t-as=\\"depth\\">\\n                <we-input t-attf-string=\\"#{display_label} #{depth}\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"null\\" t-attf-data-variable=\\"display-#{depth}-font-size\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n