1559	16	\N	1	1	Table of Content	\N	website.s_table_of_content	qweb	website/views/snippets/s_table_of_content.xml	primary	{"en_US": "<t name=\\"Table of Content\\" t-name=\\"website.s_table_of_content\\">\\n    <section class=\\"s_table_of_content pt24 pb24 o_cc o_cc1\\">\\n        <div class=\\"container\\">\\n            <div class=\\"row s_nb_column_fixed\\">\\n                <div class=\\"col-lg-3 s_table_of_content_navbar_wrap s_table_of_content_navbar_sticky s_table_of_content_vertical_navbar d-print-none d-none d-lg-block o_not_editable o_cc o_cc1\\" data-name=\\"Navbar\\">\\n                    <div class=\\"s_table_of_content_navbar list-group o_no_link_popover\\" style=\\"top: 76px; max-height: calc(100vh - 96px);\\">\\n                        <a href=\\"#table_of_content_heading_1_1\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0 active\\">Intuitive system</a>\\n                        <a href=\\"#table_of_content_heading_1_2\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0\\">Design features</a>\\n                    </div>\\n                </div>\\n                <div class=\\"col-lg-9 s_table_of_content_main oe_structure oe_empty\\" data-name=\\"Content\\">\\n                    <section class=\\"pb16\\">\\n                        <h2 id=\\"table_of_content_heading_1_1\\" data-anchor=\\"true\\">Intuitive system</h2>\\n                        <h4>What you see is what you get</h4>\\n                        <p>\\n                            Insert text styles like headers, bold, italic, lists, and fonts with\\n                            a simple WYSIWYG editor. Flexible and easy to use.\\n                        </p>\\n                        <h4>Customization tool</h4>\\n                        <p>\\n                            Click and change content directly from the front-end: no complex back\\n                            end to deal with.\\n          