ome of the first chars after 'google' is enough, we'll guess the rest.\\n                                </small>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"plausbile_setting\\" help=\\"Use Plausible.io, Simple and privacy-friendly Google Analytics alternative\\">\\n                            <field name=\\"has_plausible_shared_key\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not has_plausible_shared_key\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"Shared Link Auth\\" for=\\"plausible_shared_key\\"/>\\n                                    <field name=\\"plausible_shared_key\\" required=\\"has_plausible_shared_key\\"/>\\n                                </div>\\n                                <div class=\\"row mt16\\">\\n                                    <label class=\\"col-lg-3 o_light_label\\" string=\\"Site\\" for=\\"plausible_site\\"/>\\n                                    <field name=\\"plausible_site\\" required=\\"has_plausible_shared_key\\"/>\\n                                </div>\\n                            </div>\\n                            <div invisible=\\"not has_plausible_shared_key\\">\\n                                <a href=\\"https://www.odoo.com/documentation/17.0/applications/websites/website/reporting/plausible.html\\" class=\\"oe_link\\" target=\\"_blank\\">\\n                                    <i class=\\"oi oi-arrow-right\\"/>\\n                                    How to create my Plausible Shared Link\\n                                </a>\\n                            </div>\\n                        </setting>\\n                    </block>\\n                </app>\\n            </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                <app data-string="Website" string="Website" name="w