\\" column_invisible=\\"parent.tax_calculation_rounding_method == 'round_globally'\\" optional=\\"hide\\"/>\\n                                </tree>\\n                                <form string=\\"Purchase Order Line\\">\\n                                        <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                                        <field name=\\"state\\" invisible=\\"1\\"/>\\n                                        <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                        <group invisible=\\"display_type\\">\\n                                            <group>\\n                                                <field name=\\"product_uom_category_id\\" invisible=\\"1\\"/>\\n                                                <field name=\\"product_id\\" context=\\"{'partner_id': parent.partner_id}\\" widget=\\"many2one_barcode\\" domain=\\"[('purchase_ok', '=', True), '|', ('company_id', '=', False), ('company_id', '=', parent.company_id)]\\" readonly=\\"state in ('purchase', 'to approve', 'done', 'cancel')\\"/>\\n                                                <label for=\\"product_qty\\"/>\\n                                                <div class=\\"o_row\\">\\n                                                    <field name=\\"product_qty\\"/>\\n                                                    <field name=\\"product_uom\\" groups=\\"uom.group_uom\\" required=\\"not display_type\\"/>\\n                                                </div>\\n                                                <field name=\\"qty_received_method\\" invisible=\\"1\\"/>\\n                                                <field name=\\"qty_received\\" string=\\"Received Quantity\\" invisible=\\"parent.state not in ('purchase', 'done')\\" readonly=\\"qty_received_method != 'manual'\\"/>\\n                                                <field name=\\"qty_invoiced\\" string=\\"Billed Quantity\\" invisible=\\"parent.state not in ('purchase', 'done')\\"/>\\n                                                <field name=\\"product_packaging_qty\\" invisible=\\"not product_id or not product_packaging_id\\" groups=\\"product.group_stock_packaging\\"/>\\n                                                <field name=\\"product_packaging_id\\" invisible=\\"not product_id\\" context=\\"{'default_product_id': product_id, 'tree_view_ref':'product.product_packaging_tree_view', 'form_view_ref':'product.product_packaging_form_view'}\\" groups=\\"product.group_stock_packaging\\"/>\\n                                                <field name=\\"price_unit\\"/>\\n                                                <field name=\\"discount\\"/>\\n                                                <field name=\\"taxes_id\\" widget=\\"many2many_tags\\" domain=\\"[('type_tax_use', '=', 'purchase'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" options=\\"{'no_create': True}\\"/>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"date_planned\\" widget=\\"date\\" required=\\"not display_type\\"/>\\n                                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'purchase_order'}\\"/>\\n                                            </group>\\n                                            <group>\\n                                            <notebook colspan=\\"4\\">\\n                                                <page string=\\"Notes\\" name=\\"notes\\">\\n                                                    <field name=\\"name\\"/>\\n                                                </page>\\n                                                <page string=\\"Invoices and Incoming Shipments\\" name=\\"invoices_incoming_shiptments\\">\\n                                                    <field name=\\"invoice_lines\\"/>\\n                                                </page>\\n                                            </notebook>\\n                                            </group>\\n                                        </group>\\n                                        <label for=\\"name\\" string=\\"Section Name (eg. Products, Services)\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                        <label for=\\"name\\" string=\\"Note\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                        <field name=\\"name\\" nolabel=\\"1\\" invisible=\\"not display_type\\"/>\\n                                </form>\\n                                <kanban class=\\"o_kanban_mobile\\">\\n                                     <field name=\\"name\\"/>\\n                                     <field name=\\"product_id\\"/>\\n                                     <field name=\\"product_qty\\"/>\\n                                     <field name=\\"product_uom\\" groups=\\"uom.group_uom\\"/>\\n                                     <field name=\\"price_subtotal\\"/>\\n                                     <field name=\\"price_tax\\"/>\\n                                     <field name=\\"price_total\\"/>\\n                                     <field name=\\"price_unit\\"/>\\n                                     <field name=\\"discount\\"/>\\n                                     <field name=\\"display_type\\"/>\\n                                     <field name=\\"taxes_id\\"/>\\n                                     <field name=\\"tax_calculation_rounding_method\\"/>\\n                                     <templates>\\n                                         <t t-name=\\"kanban-box\\">\\n                                             <div t-attf-class=\\"oe_kanban_card oe_kanban_global_click {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}\\">\\n                                                 <t t-if=\\"!record.display_type.raw_value\\">\\n                                                     <div class=\\"row\\">\\n                                                         <div class=\\"col-8\\">\\n                                                             <strong>\\n                                                                 <span t-esc=\\"record.product_id.value\\"/>\\n                                                             </strong>\\n                                                         </div>\\n                                                         <div class=\\"col-4\\">\\n                                                             <strong>\\n                                                                 <span>\\n                                                                     Tax excl.: <t t-esc=\\"record.price_subtotal.value\\" class=\\"float-end text-end\\"/>\\n                                                                 </span>\\n                                                             </strong>\\n                                                         </div>\\n                                                     </div>\\n                                                     <div class=\\"row\\">\\n                                                         <div class=\\"col-8 text-muted\\">\\n                                                             <span>\\n                                                                 Quantity:\\n                                                                 <t t-esc=\\"record.product_qty.value\\"/>\\n                                                                 <small> <t t-esc=\\"record.product_uom.value\\" groups=\\"uom.group_uom\\"/></small>\\n                                                             </span>\\n                                                         </div>\\n                                                         <div class=\\"col-4\\" t-if=\\"record.tax_calculation_rounding_method.raw_value === 'round_per_line'\\">\\n                                                             <strong>\\n                                                                <span>\\n                                                                    Tax incl.: <t t-esc=\\"record.price_total.value\\"/>\\n                                                                </span>\\n                                                             </strong>\\n                                                         </div>\\n                                                     </div>\\n                                                     <div class=\\"row\\">\\n                                                         <div class=\\"col-12 text-muted\\">\\n                                                             <span>\\n                                                                 Unit Price:\\n                                                                 <field name=\\"price_unit\\"/>\\n                                                             </span>\\n                                                         </div>\\n                                                     </div>\\n                                                     <div class=\\"row\\" t-if=\\"record.discount.raw_value\\">\\n                                                         <div class=\\"col-12 text-muted\\">\\n                                                            <span>\\n                                                                Discount: <t t-out=\\"record.discount.value\\"/>%\\n                                                            </span>\\n                                                         </div>\\n                                                     </div>\\n                                                 </t>\\n                                                 <div t-elif=\\"record.display_type.raw_value === 'line_section' || record.display_type.raw_value === 'line_note'\\" class=\\"row\\">\\n                                                     <div class=\\"col-12\\">\\n                                                         <span t-esc=\\"record.name.value\\"/>\\n                                                     </div>\\n                                                 </div>\\n                                             </div>\\n                                         </t>\\n                                     </templates>\\n                                 </kanban>\\n                            </field>\\n                            <group>\\n                                <group>\\n                                    <field colspan=\\"2\\" name=\\"notes\\" nolabel=\\"1\\" placeholder=\\"Define your terms and conditions ...\\"/>\\n                                </group>\\n                                <group class=\\"oe_subtotal_footer\\">\\n                                    <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                            <div class=\\"clearfix\\"/>\\n                        </page>\\n                        <page string=\\"Other Information\\" name=\\"purchase_delivery_invoice\\">\\n                            <group>\\n                                <group name=\\"other_info\\">\\n                                    <field name=\\"user_id\\" domain=\\"[('share', '=', False)]\\" widget=\\"many2one_avatar_user\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" readonly=\\"state in ['cancel', 'done', 'purchase']\\"/>\\n                                    <field name=\\"origin\\"/>\\n                                </group>\\n                                <group name=\\"invoice_info\\">\\n                                    <field name=\\"invoice_status\\" invisible=\\"state in ('draft', 'sent', 'to approve', 'cancel')\\"/>\\n                                    <field name=\\"payment_term_id\\" readonly=\\"invoice_status == 'invoiced' or state == 'done'\\" options=\\"{'no_create': True}\\"/>\\n                                    <field name=\\"fiscal_position_id\\" options=\\"{'no_create': True}\\" readonly=\\"invoice_status == 'invoiced' or state == 'done'\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <div class=\\"oe_chatter\\">\\n                    <field name=\\"message_follower_ids\\"/>\\n                    <field name=\\"activity_ids\\"/>\\n                    <field name=\\"message_ids\\"/>\\n                </div>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Purchase Order" class="o_purchase_order">\n                <header>\n                    <button name="action_rfq_send" invisible="state != 'draft'" string="Send by Email" type="object" context="{'send_rfq':True}" class="oe_highlight" data-hotkey="g"/>\n                    <button name="print_quotation" string="Print RFQ" type="object" invisible="state != 'draft'" class="oe_highlight" groups="base.group_user" data-hotkey="k"/>\n                    <button name="button_confirm" type="object" invisible="state != 'sent'" string="Confirm Order" context="{'validate_analytic': True}" class="oe_highlight" id="bid_confirm" data-hotkey="q"/>\n                    <button name="button_approve" type="object" invisible="state != 'to approve'" string="Approve Order" class="oe_highlight" groups="purchase.group_purchase_manager" data-hotkey="z"/>\n                    <button name="action_create_invoice" string="Create Bill" type="object" class="oe_highlight" context="{'create_bill':True}" invisible="state not in ('purchase', 'done') or invoice_status in ('no', 'invoiced')" data-hotkey="w"/>\n                    <button name="action_rfq_send" invisible="state != 'sent'" string="Re-Send by Email" type="object" context="{'send_rfq':True}" data-hotkey="g"/>\n                    <button name="print_quotation" string="Print RFQ" type="object" invisible="state != 'sent'" groups="base.group_user" data-hotkey="k"/>\n                    <button name="button_confirm" type="object" invisible="state != 'draft'" context="{'validate_analytic': True}" string="Confirm Order" id="draft_confirm" data-hotkey="q"/>\n                    <button name="action_rfq_send" invisible="state != 'purchase'" string="Send PO by Email" type="object" context="{'send_rfq':False}" data-hotkey="g"/>\n                    <button name="confirm_reminder_mail" string="Confirm Receipt Date" type="object" invisible="state not in ('purchase', 'done') or mail_reminder_confirmed or not date_planned" groups="base.group_no_one" data-hotkey="o"/>\n                    <button name="action_create_invoice" string="Create Bill" type="object" context="{'create_bill':True}" invisible="state not in ('purchase', 'done') or invoice_status not in ('no', 'invoiced') or not order_line" data-hotkey="w"/>\n                    <button name="button_draft" invisible="state != 'cancel'" string="Set to Draft" type="object" data-hotkey="o"/>\n                    <button name="button_cancel" invisible="state not in ('draft', 'to approve', 'sent', 'purchase')" string="Cancel" type="object" data-hotkey="x"/>\n                    <button name="button_done" type="object" string="Lock" invisible="state != 'purchase'" data-hotkey="l"/>\n                    <button name="button_unlock" type="object" string="Unlock" invisible="state != 'done'" groups="purchase.group_purchase_manager" data-hotkey="l"/>\n                    <field name="state" widget="statusbar" statusbar_visible="draft,sent,purchase" readonly="1"/>\n                </header>\n                <sheet>\n                    <div class="oe_button_box" name="button_box">\n                        <button type="object" name="action_view_invoice" class="oe_stat_button" icon="fa-pencil-square-o" invisible="invoice_count == 0 or state in ('draft', 'sent', 'to approve')">\n                            <field name="invoice_count" widget="statinfo" string="Vendor Bills"/>\n                            <field name="invoice_ids" invisible="1"/>\n                        </button>\n                    </div>\n                    <div class="oe_title">\n                        <span class="o_form_label" invisible="state not in ('draft', 'sent')">Request for Quotation </span>\n                        <span class="o_form_label" invisible="state in ('draft', 'sent')">Purchase Order </span>\n                        <h1 class="d-flex">\n                            <field name="priority" widget="priority" class="me-3"/>\n                            <field name="name" readonly="1"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name="partner_id" widget="res_partner_many2one" context="{'res_partner_search_mode': 'supplier', 'show_vat': True}" placeholder="Name, TIN, Email, or Reference" readonly="state in ['cancel', 'done', 'purchase']"/>\n                            <field name="partner_ref"/>\n                            <field name="currency_id" groups="base.group_multi_currency" force_save="1" readonly="state in ['cancel', 'done', 'purchase']"/>\n                            <field name="id" invisible="1"/>\n                            <field name="company_id" invisible="1" readonly="state in ['cancel', 'done', 'purchase']"/>\n                            <field name="currency_id" invisible="1" readonly="state in ['cancel', 'done', 'purchase']" groups="!base.group_multi_currency"/>\n                            <field name="tax_calculation_rounding_method" invisible="1"/>\n                        </group>\n                        <group>\n                            <field name="date_order" invisible="state in ('purchase', 'done')" readonly="state in ['cancel', 'done', 'purchase']"/>\n                            <label for="date_approve" invisible="state not in ('purchase', 'done')"/>\n                            <div name="date_approve" invisible="state not in ('purchase', 'done')" class="o_row">\n                                <field name="date_approve"/>\n                                <field name="mail_reception_confirmed" invisible="1"/>\n                                <span class="text-muted" invisible="not mail_reception_confirmed">(confirmed by vendor)</span>\n                            </div>\n                            <label for="date_planned"/>\n                            <div name="date_planned_div" class="o_row">\n                                <field name="date_planned" readonly="state not in ('draft', 'sent', 'to approve', 'purchase')"/>\n                                <field name="mail_reminder_confirmed" invisible="1"/>\n                                <span class="text-muted" invisible="not mail_reminder_confirmed">(confirmed by vendor)</span>\n                            </div>\n                            <label for="receipt_reminder_email" class="d-none" groups="purchase.group_send_reminder"/>\n                            <div name="reminder" class="o_row" groups="purchase.group_send_reminder" title="Automatically send a confirmation email to the vendor X days before the expected receipt date, asking him to confirm the exact date.">\n                                <field name="receipt_reminder_email"/>\n                                <span>Ask confirmation</span>\n                                <div class="o_row oe_inline" invisible="not receipt_reminder_email">\n                                    <field name="reminder_date_before_receipt"/>\n                                    day(s) before\n                                    <widget name="toaster_button" button_name="send_reminder_preview" title="Preview the reminder email by sending it to yourself." invisible="not id"/>\n                                </div>\n                            </div>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string="Products" name="products">\n                            <field name="tax_country_id" invisible="1"/>\n                            <field name="order_line" widget="section_and_note_one2many" mode="tree,kanban" context="{'default_state': 'draft'}" readonly="state in ('done', 'cancel')">\n                                <tree string="Purchase Order Lines" editable="bottom">\n                                    <control>\n                                        <create name="add_product_control" string="Add a product"/>\n                                        <create name="add_section_control" string="Add a section" context="{'default_display_type': 'line_section'}"/>\n                                        <create name="add_note_control" string="Add a note" context="{'default_display_type': 'line_note'}"/>\n                                        <button name="action_add_from_catalog" string="Catalog" type="object" class="px-4 btn-link" context="{'order_id': parent.id}"/>\n                                    </control>\n                                    <field name="tax_calculation_rounding_method" column_invisible="True"/>\n                                    <field name="display_type" column_invisible="True"/>\n                                    <field name="company_id" column_invisible="True"/>\n                                    <field name="currency_id" column_invisible="True"/>\n                                    <field name="state" column_invisible="True"/>\n                                    <field name="product_type" column_invisible="True"/>\n                                    <field name="product_uom" column_invisible="True" groups="!uom.group_uom"/>\n                                    <field name="product_uom_category_id" column_invisible="True"/>\n                                    <field name="invoice_lines" column_invisible="True"/>\n                                    <field name="sequence" widget="handle"/>\n                                    <field name="product_id" readonly="state in ('purchase', 'to approve', 'done', 'cancel')" required="not display_type" width="35%" context="{'partner_id': parent.partner_id, 'quantity': product_qty, 'company_id': parent.company_id, 'use_partner_name': False}" force_save="1" domain="[('purchase_ok', '=', True), '|', ('company_id', '=', False), ('company_id', 'parent_of', parent.company_id)]"/>\n                                    <field name="name" widget="section_and_note_text"/>\n                                    <field name="date_planned" optional="hide" required="not display_type" force_save="1"/>\n                                    <field name="analytic_distribution" widget="analytic_distribution" optional="hide" groups="analytic.group_analytic_accounting" options="{'product_field': 'product_id', 'business_domain': 'purchase_order', 'amount_field': 'price_subtotal'}"/>\n                                    <field name="product_qty"/>\n                                    <field name="qty_received_manual" column_invisible="True"/>\n                                    <field name="qty_received_method" column_invisible="True"/>\n                                    <field name="qty_received" string="Received" column_invisible="parent.state not in ('purchase', 'done')" readonly="qty_received_method != 'manual'" optional="show"/>\n                                    <field name="qty_invoiced" string="Billed" column_invisible="parent.state not in ('purchase', 'done')" optional="show"/>\n                                    <field name="product_uom" string="UoM" groups="uom.group_uom" readonly="state in ('purchase', 'done', 'cancel')" required="not display_type" options="{'no_open': True}" force_save="1" optional="show"/>\n                                    <field name="product_packaging_qty" invisible="not product_id or not product_packaging_id" groups="product.group_stock_packaging" optional="show"/>\n                                    <field name="product_packaging_id" invisible="not product_id" context="{'default_product_id': product_id, 'tree_view_ref':'product.product_packaging_tree_view', 'form_view_ref':'product.product_packaging_form_view'}" groups="product.group_stock_packaging" optional="show"/>\n                                    <field name="price_unit" readonly="qty_invoiced != 0"/>\n                                    <button name="action_purchase_history" type="object" icon="fa-history" title="Purchase History" invisible="not id"/>\n                                    <field name="taxes_id" widget="many2many_tags" domain="[('type_tax_use', '=', 'purchase'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id), ('active', '=', True)]" context="{'default_type_tax_use': 'purchase', 'search_view_ref': 'account.account_tax_view_search'}" options="{'no_create': True}" optional="show"/>\n                                    <field name="discount" string="Disc.%" readonly="qty_invoiced != 0" optional="hide"/>\n                                    <field name="price_subtotal" string="Tax excl."/>\n                                    <field name="price_total" string="Tax incl." column_invisible="parent.tax_calculation_rounding_method == 'round_globally'" optional="hide"/>\n                                </tree>\n                                <form string="Purchase Order Line">\n                                        <field name="tax_calculation_rounding_method" invisible="1"/>\n                                        <field name="state" invisible="1"/>\n                                        <field name="display_type" invisible="1"/>\n                                        <field name="company_id" invisible="1"/>\n                                        <group invisible="display_type">\n                                            <group>\n                                                <field name="product_uom_category_id" invisible="1"/>\n                                                <field name="product_id" context="{'partner_id': parent.partner_id}" widget="many2one_barcode" domain="[('purchase_ok', '=', True), '|', ('company_id', '=', False), ('company_id', '=', parent.company_id)]" readonly="state in ('purchase', 'to approve', 'done', 'cancel')"/>\n                                                <label for="product_qty"/>\n                                                <div class="o_row">\n                                                    <field name="product_qty"/>\n                                                    <field name="product_uom" groups="uom.group_uom" required="not display_type"/>\n                                                </div>\n                                                <field name="qty_received_method" invisible="1"/>\n                                                <field name="qty_received" string="Received Quantity" invisible="parent.state not in ('purchase', 'done')" readonly="qty_received_method != 'manual'"/>\n                                                <field name="qty_invoiced" string="Billed Quantity" invisible="parent.state not in ('purchase', 'done')"/>\n                                                <field name="product_packaging_qty" invisible="not product_id or not product_packaging_id" groups="product.group_stock_packaging"/>\n                                                <field name="product_packaging_id" invisible="not product_id" context="{'default_product_id': product_id, 'tree_view_ref':'product.product_packaging_tree_view', 'form_view_ref':'product.product_packaging_form_view'}" groups="product.group_stock_packaging"/>\n                                                <field name="price_unit"/>\n                                                <field name="discount"/>\n                                                <field name="taxes_id" widget="many2many_tags" domain="[('type_tax_use', '=', 'purchase'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]" options="{'no_create': True}"/>\n                                            </group>\n                                            <group>\n                                                <field name="date_planned" widget="date" required="not display_type"/>\n                                                <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{'product_field': 'product_id', 'business_domain': 'purchase_order'}"/>\n                                            </group>\n                                            <group>\n                                            <notebook colspan="4">\n                                                <page string="Notes" name="notes">\n                                                    <field name="name"/>\n                                                </page>\n                                                <page string="Invoices and Incoming Shipments" name="invoices_incoming_shiptments">\n                                                    <field name="invoice_lines"/>\n                                                </page>\n                                            </notebook>\n                                            </group>\n                                        </group>\n                                        <label for="name"