-class="'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''">\n                            <t t-if="not line.display_type">\n                                <td id="product">\n                                    <span t-field="line.name"/>\n                                </td>\n                                <td class="text-center">\n                                    <span t-field="line.date_planned"/>\n                                </td>\n                                <td class="text-end">\n                                    <span t-field="line.product_qty"/>\n                                    <span t-field="line.product_uom.name" groups="uom.group_uom"/>\n                                    <span t-if="line.product_packaging_id">\n                                        (<span t-field="line.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="line.product_packaging_id"/>)\n                                    </span>\n                                </td>\n                                <td class="text-end">\n                                    <span t-field="line.price_unit"/>\n                                </td>\n                                <td class="text-end">\n                                    <span class="text-align-bottom"><span t-field="line.discount"/>%</span>\n                                </td>\n                                <t t-set="taxes" t-value="', '.join([(tax.invoice_label or tax.name) for tax in line.taxes_id])"/>\n                                <td name="td_taxes" t-attf-class="text-end {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}">\n                                    <span t-out="taxes">Tax 15%</span>\n                                </td>\n                                <td class="text-end">\n                                    <span t-field="line.price_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                </td>\n                            </t>\n                            <t t-if="line.display_type == 'line_section'">\n                                <td colspan="99" id="section">\n                                    <span t-field="line.name"/>\n                                </td>\n                                <t t-set="current_section" t-value="line"/>\n                                <t t-set="current_subtotal" t-value="0"/>\n                            </t>\n                            <t t-if="line.display_type == 'line_note'">\n                                <td colspan="99" id="note">\n                                    <span t-field="line.name"/>\n                                </td>\n                            </t>\n                        </tr>\n                        <t t-if="current_section and (line_last or o.order_line[line_index+1].display_type == 'line_section')">\n                            <tr class="is-subtotal text-end">\n                                <td colspan="99" id="subtotal">\n                                    <strong class="mr16">Subtotal</strong>\n                                    <span t-esc="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                </td>\n                            </tr>\n                        </t>\n                    </t>\n                </tbody>\n            </table>\n\n            <div id="total" class="row justify-content-end">\n                <div class="col-4">\n                    <table class="table table-sm table-borderless">\n                        <t t-set="tax_totals" t-value="o.tax_totals"/>\n                        <t t-call="purchase.document_tax_totals"/>\n                    </table>\n                </div>\n            </div>\n\n            <p t-field="o.notes" class="mt-4"/>\n            <div class="oe_structure"/>\n        </div>\n    </t>\n</t>\n\n	f	t	2026-04-14 18:12:07.344559	2026-04-14 18:12:07.344559	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
