ref="order.get_portal_url(report_type='pdf')" id="print_invoice_report" title="View Details" target="_blank"><i class="fa fa-print"/> View Details</a>\n                                  </div>\n                              </div>\n                          </div>\n\n                          <div class="navspy flex-grow-1 ps-0" t-ignore="true" role="complementary">\n                              <ul class="nav flex-column bs-sidenav"/>\n                          </div>\n\n                          <div t-if="order.user_id">\n                              <h6><small class="text-muted">Purchase Representative</small></h6>\n                              <div class="o_portal_contact_details d-flex flex-column gap-2">\n                                <div class="d-flex justify-content-start align-items-center gap-2">\n                                    <img class="o_avatar o_portal_contact_img rounded" t-att-src="image_data_uri(order.user_id.avatar_128)" alt="Contact"/>\n                                    <div>\n                                        <h6 class="mb-0" t-out="order.user_id.name"/>\n                                        <a href="#discussion" class="small fw-bold">Send message</a>\n                                    </div>\n                                </div>\n                                <div t-field="order.user_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;phone&quot;], &quot;no_marker&quot;: False}"/>\n                            </div>\n                          </div>\n                      </div>\n                  </t>\n              </t>\n\n              <!-- Page content -->\n              <div id="quote_content" class="o_portal_content col-12 col-lg-9 col-xl-8">\n\n                  <!-- status messages -->\n                  <div t-if="order.state == 'cancel'" class="alert alert-danger alert-dismissable d-print-none" role="alert">\n                      <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>\n                      <strong>This purchase has been canceled.</strong>\n                  </div>\n\n                  <!-- main content -->\n                  <div id="portal_purchase_content">\n                      <div t-call="purchase.purchase_order_portal_content"/>\n                  </div>\n\n                  <!-- chatter -->\n                  <hr/>\n                  <div id="purchase_order_communication">\n                      <h3>Communication history</h3>\n                      <t t-call="portal.message_thread"/>\n                  </div>\n              </div><!-- // #quote_content -->\n          </div>\n      </xpath>\n  <xpath expr="." position="attributes"><attribute name="t-name">purchase.portal_my_purchase_order</attribute></xpath></data>\n\n  	f	t	2026-04-14 18:12:07.344559	2026-04-14 18:12:07.344559	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
2161	16	\N	1	1	Purchase Order Portal Content	\N	purchase.purchase_order_portal_content	qweb	purchase/views/portal_templates.xml	primary	{"en_US": "<t name=\\"Purchase Order Portal Content\\" t-name=\\"purchase.purchase_order_portal_content\\">\\n      <!-- Intro -->\\n      <div id=\\"introduction\\" class=\\"mt-5 mt-lg-0 pb-2 pt-0\\">\\n        <h2 class=\\"my-0\\">\\n          <t t-if=\\"order.state in ['draft', 'sent']\\">Request for Quotation</t>\\n          <t t-else=\\"1\\">\\n            Purchase Order\\n          </t>\\n          <em t-esc=\\"order.name\\"/>\\n        </h2>\\n      </div>\\n\\n      <div>\\n          <!-- Informations -->\\n          <div id=\\"informations\\">\\n              <div class=\\"row\\" id=\\"po_date\\">\\n                  <div class=\\"mb-3 col-6\\">\\n                    <t t-if=\\"order.state in ['draft', 'sent']\\">\\n                      <strong>Request For Quotation Date:</strong>\\n                    </t>\\n                    <t t-if=\\"order.state in ['purchase', 'done', 'cancel']\\">\\n                      <strong>Order Date:</strong>\\n                    </t>\\n                    <span t-field=\\"order.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                  </div>\\n              </div>\\n              <div class=\\"row\\">\\n                  <div class=\\"col-lg-6\\">\\n                    <strong class=\\"d-block mb-1\\">From:</strong>\\n                    <address t-field=\\"order.company_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                    <strong>Confirmation Date:</strong> <span t-field=\\"order.date_approve\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/><br/>\\n                    <div t-att-class=\\"'d-inline' if order.date_planned else 'd-none'\\">\\n                      <strong>Receipt Date:</strong><span class=\\"ms-1\\" t-field=\\"order.date_planned\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                    </div>\\n                  </div>\\n              </div>\\n\\n              <t t-set=\\"invoices\\" t-value=\\"[i for i in order.invoice_ids if i.state not in ['draft', 'cancel']]\\"/>\\n              <div t-if=\\"invoices\\" class=\\"row\\">\\n                  <div class=\\"col\\">\\n                      <strong class=\\"d-block mb-1\\">Invoices</strong>\\n                      <ul class=\\"list-group mb-4\\">\\n                          <t t-foreach=\\"invoices\\" t-as=\\"i\\">\\n                              <t t-set=\\"report_url\\" t-value=\\"i.get_portal_url(report_type='pdf', download=True)\\"/>\\n                              <div class=\\"d-flex flex-wrap align-items-center justify-content-between\\">\\n                                  <div>\\n                                      <a t-att-href=\\"report_url\\">\\n                                          <span t-esc=\\"i.name\\"/>\\n                                      </a>\\n                                      <div class=\\"small d-lg-inline-block\\">Date: <span class=\\"text-muted\\" t-field=\\"i.invoice_date\\"/></div>\\n                                  </div>\\n                                  <span t-if=\\"i.payment_state in ('paid', 'in_payment')\\" class=\\"badge text-bg-success small\\"><i class=\\"fa fa-fw fa-check\\"/>Paid</span>\\n                                  <span t-elif=\\"i.payment_state == 'reversed'\\" class=\\"badge text-bg-success small\\"><i class=\\"fa fa-fw fa-check\\"/>Reversed</span>\\n                                  <span t-else=\\"\\" class=\\"small badge text-bg-primary\\"><i class=\\"fa fa-fw fa-clock-o\\"/>Waiting Payment</span>\\n                              </div>\\n                          </t>\\n                      </ul>\\n                  </div>\\n              </div>\\n          </div>\\n\\n          <section id=\\"details\\" style=\\"page-break-inside: auto;\\" class=\\"mt32\\">\\n              <h3 id=\\"details\\">Pricing</h3>\\n\\n              <div class=\\"table-responsive\\">\\n                <table t-att-data-order-id=\\"order.id\\" t-att-data-token=\\"order.access_token\\" class=\\"table table-sm\\" id=\\"purchase_order_table\\">\\n                    <thead class=\\"bg-100\\">\\n                        <tr>\\n                            <th class=\\"text-start\\">Products</th>\\n                            <th class=\\"text-end\\">Quantity</th>\\n                            <th t-if=\\"update_dates\\" class=\\"text-end\\">Scheduled Date</th>\\n                            <th t-if=\\"not update_dates and order.state in ['purchase', 'done']\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">Unit Price</th>\\n                            <th t-if=\\"not update_dates and order.state in ['purchase', 'done']\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                <span>Taxes</span>\\n                            </th>\\n                            <th class=\\"text-end\\" t-if=\\"order.state in ['purchase', 'done']\\">\\n                                <span>Amount</span>\\n                            </th>\\n                        </tr>\\n                    </thead>\\n                    <tbody class=\\"purchase_tbody\\">\\n\\n                          <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n\\n                          <t t-foreach=\\"order.order_line\\" t-as=\\"line\\">\\n\\n                              <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\"/>\\n\\n                            <tr t-att-class=\\"'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic text-break' if line.display_type == 'line_note' else ''\\">\\n                                <t t-if=\\"not line.display_type\\">\\n                                    <td id=\\"product_name\\">\\n                                        <img t-att-src=\\"image_data_uri(resize_to_48(line.product_id.image_1024))\\" alt=\\"Product\\" class=\\"d-none d-lg-inline\\"/>\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\">\\n                                        <div id=\\"quote_qty\\">\\n                                            <span t-field=\\"line.product_qty\\"/>\\n                                            <span t-field=\\"line.product_uom\\" groups=\\"uom.group_uom\\"/>\\n                                        </div>\\n                                    </td>\\n                                    <td t-if=\\"update_dates\\" class=\\"text-end\\">\\n                                        <div class=\\"container\\">\\n                                          <div class=\\"mb-3\\">\\n                                            <div class=\\"input-group date\\">\\n                                                <input type=\\"text\\" class=\\"form-control datetimepicker-input o-purchase-datetimepicker text-end\\" t-att-data-access-token=\\"order.access_token\\" t-att-data-order-id=\\"order.id\\" t-att-data-line-id=\\"line.id\\" t-att-data-value=\\"line.date_planned.isoformat()\\"/>\\n                                            </div>\\n                                          </div>\\n                                        </div>\\n                                    </td>\\n                                    <td t-if=\\"not update_dates and order.state in ['purchase', 'done']\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <div t-field=\\"line.price_unit\\" class=\\"text-end\\"/>\\n                                    </td>\\n                                    <td t-if=\\"not update_dates and order.state in ['purchase', 'done']\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <span t-esc=\\"', '.join(map(lambda x: (x.description or x.name), line.taxes_id))\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\" t-if=\\"not update_dates and order.state in ['purchase', 'done']\\">\\n                                        <span class=\\"oe_order_line_price_subtotal\\" t-field=\\"line.price_subtotal\\"/>\\n                                    </td>\\n                                </t>\\n                                <t t-if=\\"line.display_type == 'line_section'\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                    <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                </t>\\n                                <t t-if=\\"line.display_type == 'line_note'\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                </t>\\n                            </tr>\\n\\n                            <t t-if=\\"current_section and (line_last or order.order_line[line_index+1].display_type == 'line_section') and order.state in ['purchase', 'done']\\">\\n                                <tr class=\\"is-subtotal text-end\\">\\n                                    <td colspan=\\"99\\">\\n                                        <strong class=\\"mr16\\">Subtotal</strong>\\n                                        <span t-esc=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}\\"/>\\n                                    </td>\\n                                </tr>\\n                            </t>\\n                        </t>\\n                    </tbody>\\n                </table>\\n              </div>\\n\\n              <div id=\\"total\\" t-if=\\"order.state in ['purchase', 'done']\\" class=\\"row\\" name=\\"total\\" style=\\"page-break-inside: avoid;\\">\\n                  <div t-attf-class=\\"#{'col-4' if report_type != 'html' else 'col-sm-7 col-md-5'} ms-auto\\">\\n                      <t t-call=\\"purchase.purchase_order_portal_content_totals_table\\"/>\\n                  </div>\\n              </div>\\n          </section>\\n\\n          <section id=\\"terms\\" class=\\"mt-5\\" t-if=\\"order.notes\\">\\n              <h3 class=\\"\\">Terms &amp; Conditions</h3>\\n              <hr class=\\"mt-0 mb-1\\"/>\\n              <em t-field=\\"order.notes\\"/>\\n          </section>\\n\\n          <section class=\\"mt-5\\" t-if=\\"order.payment_term_id\\">\\n              <h3 class=\\"\\">Payment terms</h3>\\n              <hr class=\\"mt-0 mb-1\\"/>\\n              <span t-field=\\"order.payment_term_id\\"/>\\n          </section>\\n      </div>\\n  </t>"}	<?xml version="1.0"?>\n<t name="Purchase Order Portal Content" t-name="purchase.purchase_order_portal_content">\n      <!-- Intro -->\n      <div id="introduction" class="mt-5 mt-lg-0 pb-2 pt-0">\n        <h2 class="my-0">\n          <t t-if="order.state in ['draft', 'sent']">Request for Quotation</t>\n          <t t-else="1">\n            Purchase Order\n          </t>\n          <em t-esc="order.name"/>\n        </h2>\n      </div>\n\n      <div>\n          <!-- Informations -->\n          <div id="informations">\n              <div class="row" id="po_date">\n                  <div class="mb-3 col-6">\n                    <t t-if="order.state in ['draft', 'sent']">\n                      <strong>Request For Quotation Date:</strong>\n                    </t>\n                    <t t-if="order.state in ['purchase', 'done', 'cancel']">\n                      <strong>Order Date:</strong>\n                    </t>\n                    <span t-field="order.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>\n                  </div>\n              </div>\n              <div class="row">\n                  <div class="col-lg-6">\n                    <strong class="d-block mb-1">From:</strong>\n                    <address t-field="order.company_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                    <strong>Confirmation Date:</strong> <span t-field="order.date_approve" t-options="{&quot;widget&quot;: &quot;date&quot;}"/><br/>\n                    <div t-att-class="'d-inline' if order.date_planned else 'd-none'">\n                      <strong>Receipt Date:</strong><span class="ms-1" t-field="order.date_planned" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>\n                    </div>\n                  </div>\n              </div>\n\n              <t t-set="invoices" t-value="[i for i in order.invoice_ids if i.state not in ['draft', 'cancel']]"/>\n              <div t-if="invoices" class="row">\n                  <div class="col">\n                      <strong class="d-block mb-1">Invoices</strong>\n                      <ul class="list-group mb-4">\n                          <t t-foreach="invoices" t-as="i">\n                              <t t-set="report_url" t-value="i.get_portal_url(report_type='pdf', download=True)"/>\n                              <div class="d-flex flex-wrap align-items-center justify-content-between">\n                                  <div>\n                                      <a t-att-href="report_url">\n                                          <span t-esc="i.name"/>\n                                      </a>\n                                      <div class="small d-lg-inline-block">Date: <span class="text-muted" t-field="i.invoice_date"/></div>\n                                  </div>\n                                  <span t-if="i.payment_state in ('paid', 'in_payment')" class="badge text-bg-success small"><i class="fa fa-fw fa-check"/>Paid</span>\n                                  <span t-elif="i.payment_state == 'reversed'" class="badge text-bg-success small"><i class="fa fa-fw fa-check"/>Reversed</span>\n                                  <span t-else="" class="small badge text-bg-primary"><i class="fa fa-fw fa-clock-o"/>Waiting Payment</span>\n                              </div>\n                          </t>\n                      </ul>\n                  </div>\n              </div>\n          </div>\n\n          <section id="details" style="page-break-inside: auto;" class="mt32">\n              <h3 id="details">Pricing</h3>\n\n              <div class="table-responsive">\n                <table t-att-data-order-id="order.id" t-att-data-token="order.access_token" class="table table-sm" id="purchase_order_table">\n                    <thead class="bg-100">\n                        <tr>\n                            <th class="text-start">Products</th>\n                            <th class="text-end">Quantity</th>\n                            <th t-if="update_dates" class="text-end">Scheduled Date</th>\n                            <th t-if="not update_dates and order.state in ['purchase', 'done']" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">Unit Price</th>\n                            <th t-if="not update_dates and order.state in ['purchase', 'done']" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                <span>Taxes</span>\n                            </th>\n                            <th class="text-end" t-if="order.state in ['purchase', 'done']">\n                                <span>Amount</span>\n                            </th>\n                        </tr>\n                    </thead>\n                    <tbody class="purchase_tbody">\n\n                          <t t-set="current_subtotal" t-value="0"/>\n\n                          <t t-foreach="order.order_line" t-as="line">\n\n                              <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>\n\n                            <tr t-att-class="'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic text-break' if line.display_type == 'line_note' else ''">\n                                <t t-if="not line.display_type">\n                                    <td id="product_name">\n                                        <img t-att-src="image_data_uri(resize_to_48(line.product_id.image_1024))" alt="Product" class="d-none d-lg-inline"/>\n                                        <span t-field="line.name"/>\n                                    </td>\n                                    <td class="text-end">\n                                        <div id="quote_qty">\n                                            <span t-field="line.product_qty"/>\n                                            <span t-field="line.product_uom" groups="uom.group_uom"/>\n                                        </div>\n                                    </td>\n                                    <td t-if="update_dates" class="text-end">\n                                        <div class="container">\n                                          <div class="mb-3">\n                                            <div class="input-group date">\n                                                <input type="text" class="form-control datetimepicker-input o-purchase-datetimepicker text-end" t-att-data-access-token="order.access_token" t-att-data-order-id="order.id" t-att-data-line-id="line.id" t-att-data-value="line.date_planned.isoformat()"/>\n                                            </div>\n                                          </div>\n                                        </div>\n                                    </td>\n                                    <td t-if="not update_dates and order.state in ['purchase', 'done']" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                        <div t-field="line.price_unit" class="text-end"/>\n                                    </td>\n                                    <td t-if="not update_dates and order.state in ['purchase', 'done']" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                        <span t-esc="', '.join(map(lambda x: (x.description or x.name), line.taxes_id))"/>\n                                    </td>\n                                    <td class="text-end" t-if="not update_dates and order.state in ['purchase', 'done']">\n                                        <span class="oe_order_line_price_subtotal" t-field="line.price_subtotal"/>\n                                    </td>\n                                </t>\n                                <t t-if="line.display_type == 'line_section'">\n                                    <td colspan="99">\n                                        <span t-field="line.name"/>\n                                    </td>\n                                    <t t-set="current_section" t-value="line"/>\n                                    <t t-set="current_subtotal" t-value="0"/>\n                                </t>\n                                <t t-if="line.display_type == 'line_note'">\n                                    <td colspan="99">\n                                        <span t-field="line.name"/>\n                                    </td>\n                                </t>\n                            </tr>\n\n               