    <t t-set="line_tax_total" t-value="line_tax_total + tax.amount"/>\n                                </t>\n                                <td style="border-right:2pt solid grey;text-align:center;padding:3pt">\n                                    <span t-field="line.name"/>\n                                    <br/>\n                                </td>\n                                <td style="border-right:2pt solid grey;text-align:center;padding:3pt">\n                                    <span t-field="line.price_unit" t-options="{&quot; widget&quot;: &quot;monetary&quot;, &quot;                                         display_currency&quot;: doc.currency_id}"/>\n                                </td>\n                                <td style="border-right:2pt solid grey;text-align:center;padding:3pt">\n                                    <span t-esc="'%.2f %s '%(line.quantity,line.product_uom_id.name)"/>\n                                </td>\n                                <td style="border-right:2pt solid grey;text-align:center;padding:3pt">\n                                    <span t-field="line.price_subtotal" t-options="{&quot; widget&quot;: &quot;monetary&quot;, &quot;                                         display_currency&quot;: doc.currency_id}"/>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                    <br/>\n                    <table style="border:2pt solid grey;width:100%;color:black;" class="table table-bordered table-sm">\n                        <thead>\n                            <tr>\n                                <td width="40%" style="font-weight: bold;text-align:left;padding:2pt">\n                                    Total Taxable\n                                    Amount (excl. VAT)\n                                </td>\n                                <td class="amount" width="40%" style="text-align:right;padding:2pt">إجمالي\n