2283	16	\N	1	1	arabic_english_invoice	\N	l10n_gcc_invoice.arabic_english_invoice	qweb	l10n_gcc_invoice/views/report_invoice.xml	primary	{"en_US": "<t t-name=\\"l10n_gcc_invoice.arabic_english_invoice\\">\\n        <t t-call=\\"web.external_layout\\">\\n            <t t-set=\\"o\\" t-value=\\"o.with_context(lang=lang)\\"/>\\n            <t t-set=\\"forced_vat\\" t-value=\\"o.fiscal_position_id.foreign_vat\\"/> <!-- So that it appears in the footer of the report instead of the company VAT if it's set -->\\n            <t t-set=\\"address\\">\\n                <address t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\" style=\\"text-align: right\\"/>\\n                <div t-if=\\"o.partner_id.vat\\" class=\\"mt16\\" style=\\"text-align: right\\">\\n                    <t t-if=\\"o.company_id.account_fiscal_country_id.vat_label\\" t-out=\\"o.company_id.account_fiscal_country_id.vat_label\\" id=\\"inv_tax_id_label\\"/>\\n                    <t t-else=\\"\\">Tax ID</t>: <span t-field=\\"o.partner_id.vat\\"/></div>\\n            </t>\\n\\n            <t t-set=\\"o_sec\\" t-value=\\"o.with_context(lang='ar_001')\\"/>\\n            <t t-set=\\"o\\" t-value=\\"o.with_context(lang='en_US')\\"/>\\n\\n            <div class=\\"page\\">\\n                <h3>\\n                    <div class=\\"row\\">\\n                        <div class=\\"col-4\\" style=\\"text-align:left\\">\\n                            <span t-if=\\"o.move_type == 'out_invoice' and o.state == 'posted'\\">\\n                                Tax Invoice\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'draft'\\">\\n                                Draft Invoice\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'cancel'\\">\\n                                Cancelled Invoice\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'posted'\\">\\n                                Credit Note\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'draft'\\">\\n                                Draft Credit Note\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'cancel'\\">\\n                                Cancelled Credit Note\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'in_refund'\\">\\n                                Vendor Credit Note\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'in_invoice'\\">\\n                                Vendor Bill\\n                            </span>\\n                        </div>\\n                        <div class=\\"col-4 text-center\\">\\n                            <span t-if=\\"o.name != '/'\\" t-field=\\"o.name\\"/>\\n                        </div>\\n                        <div class=\\"col-4\\" style=\\"text-align:right\\">\\n                            <span t-if=\\"o.move_type == 'out_invoice' and o.state == 'posted'\\">\\n                                فاتورة ضريبية\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'draft'\\">\\n                                مسودة فاتورة\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'cancel'\\">\\n                                فاتورة ملغاة\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'posted'\\">\\n                                إشعار دائن\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'draft'\\">\\n                                إشعار خصم المسودة\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'cancel'\\">\\n                                إشعار خصم ملغاة\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'in_refund'\\">\\n                                إشعار مدين\\n                            </span>\\n                            <span t-elif=\\"o.move_type == 'in_invoice'\\">\\n                                فاتورة المورد\\n                            </span>\\n                        </div>\\n                    </div>\\n                </h3>\\n\\n                <div id=\\"informations\\" class=\\"pb-3\\">\\n                    <div class=\\"row\\" t-if=\\"o.invoice_date\\" name=\\"invoice_date\\">\\n                        <div class=\\"col-2 offset-6\\">\\n                            <strong style=\\"white-space:nowrap\\">Invoice Date:\\n                            </strong>\\n                        </div>\\n                        <div class=\\"col-2\\">\\n                            <span t-field=\\"o.invoice_date\\"/>\\n                        </div>\\n                        <div class=\\"col-2 text-end\\">\\n                            <strong style=\\"white-space:nowrap\\">:\\n                                تاريخ الفاتورة\\n                            </strong>\\n                        </div>\\n                    </div>\\n                    <div class=\\"row\\" t-if=\\"o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted'\\" name=\\"due_date\\">\\n                        <div class=\\"col-2 offset-6\\">\\n                            <strong style=\\"white-space:nowrap\\">Due Date:\\n                            </strong>\\n                        </div>\\n                        <div class=\\"col-2\\">\\n                            <span t-field=\\"o.invoice_date_due\\"/>\\n                        </div>\\n                        <div class=\\"col-2 text-end\\">\\n                            <strong style=\\"white-space:nowrap\\">:\\n                                تاريخ الاستحقاق\\n                            </strong>\\n                        </div>\\n                    </div>\\n                    <div class=\\"row\\" t-if=\\"o.invoice_origin\\" name=\\"origin\\">\\n                        <div class=\\"col-2 offset-6\\">\\n                            <strong style=\\"white-space:nowrap\\">Source:\\n                            </strong>\\n                        </div>\\n                        <div class=\\"col-2\\">\\n                            <span t-field=\\"o.invoice_origin\\"/>\\n                        </div>\\n                        <div class=\\"col-2 text-end\\">\\n                            <strong style=\\"white-space:nowrap\\">:\\n                                المصدر\\n                            </strong>\\n                        </div>\\n                    </div>\\n                    <div class=\\"row\\" t-if=\\"o.partner_id.ref\\" name=\\"customer_code\\">\\n                        <div class=\\"col-2 offset-6\\">\\n                            <strong style=\\"white-space:nowrap\\">\\n                                Customer Code:\\n                            </strong>\\n                        </div>\\n                        <div class=\\"col-2\\">\\n                            <span t-field=\\"o.partner_id.ref\\"/>\\n                        </div>\\n                        <div class=\\"col-2 text-end\\">\\n                            <strong style=\\"white-space:nowrap\\">:\\n                                كود العميل\\n                            </strong>\\n                        </div>\\n                    </div>\\n                    <div class=\\"row\\" t-if=\\"o.ref\\" name=\\"reference\\">\\n                        <div class=\\"col-2 offset-6\\">\\n                            <strong style=\\"white-space:nowrap\\">Reference:\\n                            </strong>\\n                        </div>\\n                        <div class=\\"col-2\\">\\n                            <span t-field=\\"o.ref\\"/>\\n                        </div>\\n                        <div class=\\"col-2 text-end\\">\\n                            <strong style=\\"white-space:nowrap\\">:\\n                                رقم الإشارة\\n                            </strong>\\n                        </div>\\n                    </div>\\n                </div>\\n\\n                <t t-set=\\"display_discount\\" t-value=\\"any(l.discount for l in o.invoice_line_ids)\\"/>\\n                <table class=\\"table table-sm o_main_table\\" name=\\"invoice_line_table\\">\\n                    <thead>\\n                        <tr>\\n                            <t t-set=\\"colspan\\" t-value=\\"6\\"/>\\n                            <th name=\\"th_total\\" class=\\"text-end\\">\\n                                <span>\\n                                    السعر الاجمالي\\n                                </span>\\n                                <br/>\\n                                <span>\\n                                    Total Price\\n                                </span>\\n                            </th>\\n                            <th name=\\"th_tax_amount\\" class=\\"text-end\\">\\n                                <span>\\n                                    قيمة الضريبة\\n                                </span>\\n                                <br/>\\n                                <span>\\n                                    VAT Amount\\n                                </span>\\n                            </th>\\n                            <th name=\\"th_subtotal\\" class=\\"text-end\\">\\n                                <span>\\n                                    مبلغ\\n                                </span>\\n                                <br/>\\n                                <span>\\n                                    Amount\\n                                </span>\\n                            </th>\\n                            <th name=\\"th_taxes\\" class=\\"text-end\\">\\n                                <span>\\n                                    الضرائب\\n                                </span>\\n                                <br/>\\n                                <span>\\n                                    Taxes\\n                                </span>\\n                            </th>\\n                            <th name=\\"th_price_unit\\" t-if=\\"display_discount\\" class=\\"text-end\\">\\n                                <span>\\n                                    خصم %\\n                                </span>\\n                                <br/>\\n                                <span>\\n                                    Disc.%\\n                                </span>\\n                                <t t-set=\\"colspan\\" t-value=\\"colspan+1\\"/>\\n                            </th>\\n                            <th name=\\"th_priceunit\\" class=\\"text-end\\">\\n                                <span>\\n                                    سعر الوحدة\\n                                </span>\\n                                <br/>\\n                                <span>\\n                                    Unit price\\n                                </span>\\n                            </th>\\n                            <th name=\\"th_quantity\\" class=\\"text-end\\">\\n                                <span>\\n                                    الكمية\\n                                </span>\\n                                <br/>\\n                                <span>\\n                                    Quantity\\n                                </span>\\n                            </th>\\n                            <th name=\\"th_source\\" class=\\"d-none text-start\\" t-if=\\"0\\">\\n                                <span>\\n                                    المستند المصدر\\n                                </span>\\n                                <br/>\\n                                <span>\\n                                    Source Document\\n                                </span>\\n                            </th>\\n                            <th name=\\"th_description\\" class=\\"text-end\\">\\n                                <span>\\n                                    الوصف\\n                                </span>\\n                                <br/>\\n                                <span>\\n                                    Description\\n                                </span>\\n                            </th>\\n                        </tr>\\n                    </thead>\\n                    <tbody class=\\"invoice_tbody\\">\\n                        <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                        <t t-set=\\"lines\\" t-value=\\"o.invoice_line_ids.sorted(key=lambda l: (-l.sequence, l.date, l.move_name, -l.id), reverse=True)\\"/>\\n\\n                        <t t-foreach=\\"lines\\" t-as=\\"line\\">\\n                            <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\"/>\\n                            <t t-set=\\"current_total\\" t-value=\\"current_subtotal + line.price_total\\" t-if=\\"o.tax_calculation_rounding_method == 'round_per_line'\\"/>\\n\\n                            <tr t-att-class=\\"'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''\\">\\n                                <t t-if=\\"line.display_type not in ('line_note', 'line_section')\\" name=\\"account_invoice_line_accountable\\">\\n                                    <td class=\\"text-end o_price_total\\">\\n                                        <span class=\\"text-nowrap\\" t-field=\\"line.price_total\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\">\\n                                        <span class=\\"text-nowrap\\" t-field=\\"line.l10n_gcc_invoice_tax_amount\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end o_price_total\\">\\n                                        <span class=\\"text-nowrap\\" t-field=\\"line.price_subtotal\\"/>\\n                                    </td>\\n\\n                                    <td class=\\"text-end\\">\\n                                        <span t-out=\\"', '.join(map(lambda x: (x.invoice_label or x.name), line.tax_ids))\\" id=\\"line_tax_ids\\"/>\\n                                    </td>\\n                                    <td t-if=\\"display_discount\\" class=\\"text-end\\">\\n                                        <span class=\\"text-nowrap\\" t-field=\\"line.discount\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\">\\n                                        <span class=\\"text-nowrap\\" t-field=\\"line.price_unit\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\">\\n                                        <span t-field=\\"line.quantity\\"/>\\n                                        <span t-field=\\"line.product_uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                    </td>\\n                                    <td name=\\"account_invoice_line_name\\" class=\\"text-end\\">\\n                                        <t t-if=\\"line.product_id\\">\\n                                            <t t-set=\\"english_name\\" t-value=\\"line.with_context(lang='en_US').product_id.display_name\\"/>\\n                                            <t t-set=\\"arabic_name\\" t-value=\\"line.with_context(lang='ar_001').product_id.display_name\\"/>\\n\\n                                            <span t-out=\\"arabic_name + '\\\\n'\\" t-if=\\"arabic_name not in line.name\\" t-options=\\"{'widget': 'text'}\\" dir=\\"rtl\\"/>\\n                                            <span t-out=\\"english_name + '\\\\n'\\" t-if=\\"(english_name != arabic_name) and (english_name not in line.name)\\" t-options=\\"{'widget': 'text'}\\"/>\\n                                        </t>\\n                                        <span t-out=\\"line.name\\" t-options=\\"{'widget': 'text'}\\" t-att-dir=\\"o.env['res.lang']._lang_get_direction(o.partner_id.lang)\\"/>\\n                                    </td>\\n\\n                                </t>\\n                                <t t-if=\\"line.display_type == 'line_section'\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\" t-options=\\"{'widget': 'text'}\\"/>\\n                                    </td>\\n                                    <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                </t>\\n                                <t t-if=\\"line.display_type == 'line_note'\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\" t-options=\\"{'widget': 'text'}\\"/>\\n                                    </td>\\n                                </t>\\n                            </tr>\\n\\n                            <t t-if=\\"current_section and (line_last or lines[line_index+1].display_type == 'line_section')\\">\\n                                <tr class=\\"is-subtotal text-end\\">\\n                                    <td colspan=\\"99\\">\\n                                        <strong class=\\"mr16\\" style=\\"display: inline-block\\">Subtotal/الإجمالي الفرعي</strong>\\n                                        <span t-out=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\"/>\\n                                    </td>\\n                                </tr>\\n                            </t>\\n                        </t>\\n                    </tbody>\\n                </table>\\n\\n                <div class=\\"clearfix pt-4 pb-3\\">\\n                    <div id=\\"total\\" class=\\"row\\">\\n                        <div class=\\"col-6\\">\\n                            <table class=\\"table table-sm\\" style=\\"page-break-inside: avoid;\\">\\n                                <tr class=\\"border-black o_subtotal\\">\\n                                    <td class=\\"text-end\\">\\n                                        <span t-field=\\"o.amount_untaxed\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\">\\n                                        <strong>\\n                                            Subtotal\\n                                            /\\n                                            الإجمالي الفرعي\\n                                        </strong>\\n                                    </td>\\n                                </tr>\\n                                <t t-set=\\"tax_totals\\" t-value=\\"o.tax_totals\\"/>\\n                                <t t-foreach=\\"tax_totals['subtotals']\\" t-as=\\"subtotal\\">\\n                                    <t t-set=\\"subtotal_to_show\\" t-value=\\"subtotal['name']\\"/>\\n                                    <!-- copy-pasted template \\"account.tax_groups_totals\\" with reversed columns order -->\\n                                    <t t-foreach=\\"tax_totals['groups_by_subtotal'][subtotal_to_show]\\" t-as=\\"amount_by_group\\">\\n                                        <tr>\\n                                            <td class=\\"text-end o_price_total\\">\\n                                                <span class=\\"text-nowrap\\" t-esc=\\"amount_by_group['formatted_tax_group_amount']\\"/>\\n                                            </td>\\n                                            <td class=\\"text-end\\">\\n                                                <strong>\\n                                                    <span t-esc=\\"amount_by_group['tax_group_name']\\"/>\\n                                                    <t t-if=\\"tax_totals['display_tax_base']\\">\\n                                                        <span class=\\"text-nowrap\\"> on\\n                                                            <t t-esc=\\"amount_by_group['formatted_tax_group_base_amount']\\"/>\\n                                                        </span>\\n                                                    </t>\\n                                                    <!-- Arabic translation of tax group -->\\n                                                    <t t-set=\\"arabic_tax_group_name\\" t-value=\\"o_sec.tax_totals['groups_by_subtotal'][o_sec.tax_totals['subtotals'][subtotal_index]['name']][amount_by_group_index]['tax_group_name']\\"/>\\n                                                    <span t-if=\\"arabic_tax_group_name != amount_by_group['tax_group_name']\\" class=\\"text-nowrap\\">/\\n                                                        <t t-esc=\\"arabic_tax_group_name\\"/>\\n                                                    </span>\\n                                                </strong>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n\\n                                </t>\\n                                <tr class=\\"border-black o_total\\">\\n                                    <td class=\\"text-end\\">\\n                                        <span class=\\"text-nowrap\\" t-field=\\"o.amount_total\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\">\\n                                        <strong>\\n                                            Total\\n                                            /\\n                                            المجموع\\n                                        </strong>\\n                                    </td>\\n                                </tr>\\n\\n                                <t t-if=\\"print_with_payments\\">\\n                                    <t t-if=\\"o.payment_state != 'invoicing_legacy'\\">\\n                                        <t t-set=\\"payments_vals\\" t-value=\\"o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget['content'] or []\\"/>\\n                                        <t t-foreach=\\"payments_vals\\" t-as=\\"payment_vals\\">\\n                                            <tr class=\\"border-black o_total\\">\\n                                                <td>\\n                                                    <i class=\\"row\\">\\n                                                        <div class=\\"col-7 oe_form_field oe_payment_label\\">\\n                                                            Paid on/دفعت في:\\n                                                        </div>\\n                                                        <div class=\\"col-5 ps-0 oe_form_field oe_payment_label\\">\\n                                                            <t t-out=\\"payment_vals['date']\\"/>\\n                                                        </div>\\n                                                    </i>\\n                                                </td>\\n                                                <td class=\\"text-end\\">\\n                                                    <span t-out=\\"payment_vals['amount']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\"/>\\n                                                </td>\\n                                            </tr>\\n                                        </t>\\n                                        <t t-if=\\"len(payments_vals) &gt; 0\\">\\n                                            <tr class=\\"border-black\\">\\n                                                <td>\\n                                                    <strong>\\n                                                        Amount Due\\n                                                        /\\n                                                        المبلغ المستحق\\n                                                    </strong>\\n                                                </td>\\n                                                <td class=\\"text-end\\">\\n                                                    <span t-field=\\"o.amount_residual\\"/>\\n                                                </td>\\n                                            </tr>\\n                                        </t>\\n                                    </t>\\n                                </t>\\n                            </table>\\n                        </div>\\n                    </div>\\n                </div>\\n\\n                <div class=\\"mb-2\\">\\n                    <p class=\\"lh-sm\\" t-if=\\"o.company_id.display_invoice_amount_total_words\\">\\n                        Total amount in words: <br/>\\n                        <span class=\\"text-muted\\" t-field=\\"o.amount_total_words\\"/>\\n                    </p>\\n                    <p class=\\"text-end lh-sm\\" t-if=\\"o.company_id.display_invoice_amount_total_words\\">\\n                        المبلغ الإجمالي <br/>\\n                        <span class=\\"text-muted\\" t-out=\\"o._num2words(o.amount_total, 'ar_001')\\"/>\\n                    </p>\\n                </div>\\n\\n                <div t-if=\\"o.currency_id != o.company_id.currency_id\\" class=\\"row clearfix ms-auto text-nowrap border-top border-bottom p-2\\">\\n                    <t t-set=\\"exchange_rate\\" t-value=\\"abs(o.amount_total_signed) / o.amount_total if o.amount_total else 0\\"/>\\n                    <div name=\\"exchange_rate\\" t-attf-class=\\"#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'}\\">\\n                        <strong>سعر الصرف</strong><br/>\\n                        <strong>Exchange Rate</strong>\\n                        <p class=\\"m-0\\" t-out=\\"exchange_rate\\" t-options=\\"{&quot;widget&quot;: &quot;float&quot;, &quot;precision&quot;: 5}\\"/>\\n                    </div>\\n                    <div name=\\"subtotal_company_currency\\" t-attf-class=\\"#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'}\\">\\n                        <strong>الإجمالي الفرعي</strong><br/>\\n                        <strong>Subtotal</strong>\\n                        <p class=\\"m-0\\" t-out=\\"abs(o.amount_untaxed_signed)\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}\\"/>\\n                    </div>\\n                    <div name=\\"vat_amount_company_currency\\" t-attf-class=\\"#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'}\\">\\n                        <strong>قيمة الضريبة</strong><br/>\\n                        <strong>VAT Amount</strong>\\n                        <p class=\\"m-0\\" t-out=\\"abs(o.amount_tax_signed)\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}\\"/>\\n                    </div>\\n                    <div name=\\"total_company_currency\\" t-attf-class=\\"#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'}\\">\\n                        <strong>المجموع</strong><br/>\\n                        <strong>Total</strong>\\n                        <p class=\\"m-0\\" t-out=\\"abs(o.amount_total_signed)\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}\\"/>\\n                    </div>\\n                </div>\\n\\n                <p name=\\"payment_communication\\" t-if=\\"0\\"/>\\n                <div class=\\"row\\" t-if=\\"o.move_type in ('out_invoice', 'in_refund') and o.payment_reference\\" name=\\"payment_communication\\">\\n                    <div class=\\"col-2\\">\\n                        <strong>Payment Reference:</strong>\\n                    </div>\\n                    <div class=\\"col-2\\">\\n                        <span class=\\"fw-bold\\" t-field=\\"o.payment_reference\\"/>\\n                    </div>\\n                    <div class=\\"col-2 text-end\\">\\n                        <strong style=\\"white-space:nowrap\\">:رقم إشارة الدفعة</strong>\\n                    </div>\\n                </div>\\n\\n                <p t-if=\\"o.invoice_payment_term_id\\" name=\\"payment_term\\">\\n                    <div class=\\"row\\">\\n                        <div class=\\"col-3 text-start\\">\\n                            <span t-out=\\"o.invoice_payment_term_id.note\\"/>\\n                        </div>\\n                        <div class=\\"col-3 text-end\\">\\n                            <span t-if=\\"o.invoice_payment_term_id.note != o_sec.invoice_payment_term_id.note\\" dir=\\"rtl\\" t-out=\\"o_sec.invoice_payment_term_id.note\\"/>\\n                        </div>\\n                    </div>\\n                    <t t-if=\\"o.invoice_payment_term_id.display_on_invoice and o.payment_term_details\\">\\n                        <div t-if=\\"o.show_payment_term_details\\" id=\\"total_payment_term_details_table\\" class=\\"row\\">\\n                            <div t-attf-class=\\"#{'col-10 offset-2' if report_type != 'html' else 'col-sm-10 col-md-9 offset-sm-2 offset-md-3'}\\">\\n                                <t t-if=\\"o._is_eligible_for_early_payment_discount(o.currency_id,o.invoice_date)\\">\\n                                    <div class=\\"text-end\\">\\n                                        <span dir=\\"rtl\\" style=\\"white-space: normal;\\">\\n                                            <span t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax)\\">30.00</span> مستحق إذا تم الدفع قبل\\n                                            <span t-out=\\"o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)\\">2024-01-01</span>\\n                                        </span>\\n                                        <br/>\\n                                        <span t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax)\\">30.00</span> due if paid before\\n                                        <span t-out=\\"o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)\\">2024-01-01</span>\\n                                    </div>\\n                                </t>\\n                                <t t-if=\\"len(o.payment_term_details) &gt; 1\\" t-foreach=\\"o.payment_term_details\\" t-as=\\"term\\">\\n                                    <div dir=\\"rtl\\" class=\\"text-end\\" style=\\"white-space: normal;\\">\\n                                        <span t-out=\\"term_index + 1\\">1</span> - قسط\\n                                        <t t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"term.get('amount')\\">31.05</t> مستحق في\\n                                        <t t-out=\\"term.get('date')\\">2024-01-01</t>\\n                                    </div>\\n                                    <div class=\\"text-end\\">\\n                                        <span t-out=\\"term_index + 1\\">1</span> - Installment of\\n                                        <t t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"term.get('amount')\\" class=\\"text-end\\">31.05</t>\\n                                        <span> due on </span>\\n                                        <t t-out=\\"term.get('date')\\" class=\\"text-start\\">2024-01-01</t>\\n                                    </div>\\n                                </t>\\n                            </div>\\n                        </div>\\n                    </t>\\n                </p>\\n                <p t-if=\\"o.narration\\" name=\\"comment\\">\\n                    <div class=\\"row\\">\\n                        <div class=\\"col-6 text-start\\">\\n                            <span t-out=\\"o.narration\\"/>\\n                        </div>\\n                        <div class=\\"col-6 text-end\\">\\n                            <span t-if=\\"o.narration != o_sec.narration\\" dir=\\"rtl\\" t-out=\\"o_sec.narration\\"/>\\n                        </div>\\n                    </div>\\n                </p>\\n                <p t-if=\\"o.fiscal_position_id.note\\" name=\\"note\\">\\n                    <div class=\\"row\\">\\n                        <div class=\\"col-6 text-start\\">\\n                            <span t-out=\\"o.fiscal_position_id.note\\"/>\\n                        </div>\\n                        <div class=\\"col-6 text-end\\">\\n                            <span t-if=\\"o.fiscal_position_id.note != o_sec.fiscal_position_id.note\\" dir=\\"rtl\\" t-out=\\"o_sec.fiscal_position_id.note\\"/>\\n                        </div>\\n                    </div>\\n                </p>\\n                \\n                <p name=\\"incoterm\\" t-if=\\"0\\"/>\\n                <div class=\\"row\\" t-if=\\"o.invoice_incoterm_id\\" name=\\"incoterm\\">\\n                    <div class=\\"col-2 offset-6\\">\\n                        <strong>Incoterm:</strong>\\n                    </div>\\n                    <div class=\\"col-2 text-nowrap\\">\\n                        <span t-out=\\"o.invoice_incoterm_id.code\\"/>\\n                        -\\n                        <span t-out=\\"o.invoice_incoterm_id.name\\"/>\\n                        -\\n                        <span t-if=\\"o.incoterm_location\\" t-out=\\"o.incoterm_location\\"/>\\n                    </div>\\n                    <div class=\\"col-2 text-end\\">\\n                        <strong>:شرط تجاري</strong>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="l10n_gcc_invoice.arabic_english_invoice">\n        <t t-call="web.external_layout">\n            <t t-set="o" t-value="o.with_context(lang=lang)"/>\n            <t t-set="forced_vat" t-value="o.fiscal_position_id.foreign_vat"/> <!-- So that it appears in the footer of the report instead of the company VAT if it's set -->\n            <t t-set="address">\n                <address t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}" style="text-align: right"/>\n                <div t-if="o.partner_id.vat" class="mt16" style="text-align: right">\n                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-out="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>\n                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/></div>\n            </t>\n\n            <t t-set="o_sec" t-value="o.with_context(lang='ar_001')"/>\n            <t t-set="o" t-value="o.with_context(lang='en_US')"/>\n\n            <div class="page">\n                <h3>\n                    <div class="row">\n                        <div class="col-4" style="text-align:left">\n                            <span t-if="o.move_type == 'out_invoice' and o.state == 'posted'">\n                                Tax Invoice\n                            </span>\n                            <span t-elif="o.move_type == 'out_invoice' and o.state == 'draft'">\n                                Draft Invoice\n                            </span>\n                            <span t-elif="o.move_type == 'out_invoice' and o.state == 'cancel'">\n                                Cancelled Invoice\n                            </span>\n                            <span t-elif="o.move_type == 'out_refund' and o.state == 'posted'">\n                                Credit Note\n                            </span>\n                            <span t-elif="o.move_type == 'out_refund' and o.state == 'draft'">\n                                Draft Credit Note\n                            </span>\n                            <span t-elif="o.move_type == 'out_refund' and o.state == 'cancel'">\n                                Cancelled Credit Note\n                            </span>\n                            <span t-elif="o.move_type == 'in_refund'">\n                                Vendor Credit Note\n                            </span>\n                            <span t-elif="o.move_type == 'in_invoice'">\n                                Vendor Bill\n                            </span>\n                        </div>\n                        <div class="col-4 text-center">\n                            <span t-if="o.name != '/'" t-field="o.name"/>\n                        </div>\n                        <div class="col-4" style="text-align:right">\n                            <span t-if="o.move_type == 'out_invoice' and o.state == 'posted'">\n                                فاتورة ضريبية\n                            </span>\n                            <span t-elif="o.move_type == 'out_invoice' and o.state == 'draft'">\n                                مسودة فاتورة\n                            </span>\n                            <span t-elif="o.move_type == 'out_invoice' and o.state == 'cancel'">\n                                فاتورة ملغاة\n                            </span>\n                            <span t-elif="o.move_type == 'out_refund' and o.state == 'posted'">\n                                إشعار دائن\n                            </span>\n                            <span t-elif="o.move_type == 'out_refund' and o.state == 'draft'">\n                                إشعار خصم المسودة\n                            </span>\n                            <span t-elif="o.move_type == 'out_refund' and o.state == 'cancel'">\n                                إشعار خصم ملغاة\n                            </span>\n                            <span t-elif="o.move_type == 'in_refund'">\n                                إشعار مدين\n                            </span>\n                            <span t-elif="o.move_type == 'in_invoice'">\n                                فاتورة المورد\n                            </span>\n                        </div>\n                    </div>\n                </h3>\n\n                <div id="informations" class="pb-3">\n                    <div class="row" t-if="o.invoice_date" name="invoice_date">\n                        <div class="col-2 offset-6">\n                            <strong style="white-space:nowrap">Invoice Date:\n                            </strong>\n                        </div>\n                        <div class="col-2">\n                            <span t-field="o.invoice_date"/>\n                        </div>\n                        <div class="col-2 text-end">\n                            <strong style="white-space:nowrap">:\n                                تاريخ الفاتورة\n                            </strong>\n                        </div>\n                    </div>\n                    <div class="row" t-if="o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted'" name="due_date">\n                        <div class="col-2 offset-6">\n                            <strong style="white-space:nowrap">Due Date:\n                            </strong>\n                        </div>\n                        <div class="col-2">\n                            <span t-field="o.invoice_date_due"/>\n                        </div>\n                        <div class="col-2 text-end">\n                            <strong style="white-space:nowrap">:\n                                تاريخ الاستحقاق\n                            </strong>\n                        </div>\n                    </div>\n                    <div class="row" t-if="o.invoice_origin" name="origin">\n                        <div class="col-2 offset-6">\n                            <strong style="white-space:nowrap">Source:\n                            </strong>\n                        </div>\n                        <div class="col-2">\n                            <span t-field="o.invoice_origin"/>\n                        </div>\n                        <div class="col-2 text-end">\n                            <strong style="white-space:nowrap">:\n                                المصدر\n                            </strong>\n                        </div>\n                    </div>\n                    <div class="row" t-if="o.partner_id.ref" name="customer_code">\n                        <div class="col-2 offset-6">\n                            <strong style="white-space:nowrap">\n                                Customer Code:\n                            </strong>\n                        </div>\n                        <div class="col-2">\n                            <span t-field="o.partner_id.ref"/>\n                        </div>\n                        <div class="col-2 text-end">\n                            <strong style="white-space:nowrap">:\n                                كود العميل\n                            </strong>\n                        </div>\n                    </div>\n                    <div class="row" t-if="o.ref" name="reference">\n                        <div class="col-2 offset-6">\n                            <strong style="white-space:nowrap">Reference:\n                            </strong>\n                        </div>\n                        <div class="col-2">\n                            <span t-field="o.ref"/>\n                        </div>\n                        <div class="col-2 text-end">\n                            <strong style="white-space:nowrap">:\n                                رقم الإشارة\n                            </strong>\n                        </div>\n                    </div>\n                </div>\n\n                <t t-set="display_discount" t-value="any(l.discount for l in o.invoice_line_ids)"/>\n                <table class="table table-sm o_main_table" name="invoice_line_table">\n                    <thead>\n                        <tr>\n                            <t t-set="colspan" t-value="6"/>\n                            <th name="th_total" class="text-end">\n                                <span>\n                                    السعر الاجمالي\n                                </span>\n                                <br/>\n                                <span>\n                                    Total Price\n                                </span>\n                            </th>\n                            <th name="th_tax_amount" class="text-end">\n                                <span>\n                                    قيمة الضريبة\n                                </span>\n                                <br/>\n                                <span>\n                                    VAT Amount\n                                </span>\n                            </th>\n                            <th name="th_subtotal" class="text-end">\n                                <span>\n                                    مبلغ\n                                </span>\n                                <br/>\n                                <span>\n                                    Amount\n                                </span>\n                            </th>\n                            <th name="th_taxes" class="text-end">\n                                <span>\n                                    الضرائب\n                                </span>\n                                <br/>\n                                <span>\n                                    Taxes\n                                </span>\n                            </th>\n                            <th name="th_price_unit" t-if="display_discount" class="text-end">\n                                <span>\n                                    خصم %\n                                </span>\n                                <br/>\n                                <span>\n                                    Disc.%\n                                </span>\n                                <t t-set="colspan" t-value="colspan+1"/>\n                            </th>\n                            <th name="th_priceunit" class="text-end">\n                                <span>\n                                    سعر الوحدة\n                                </span>\n                                <br/>\n                                <span>\n                                    Unit price\n                                </span>\n                            </th>\n                            <th name="th_quantity" class="text-end">\n                                <span>\n                                    الكمية\n                                </span>\n                                <br/>\n                                <span>\n                                    Quantity\n                                </span>\n                            </th>\n                            <th name="th_source" class="d-none text-start" t-if="0">\n                                <span>\n                                    المستند المصدر\n                                </span>\n                                <br/>\n                                <span>\n                                    Source Document\n                                </span>\n                            </th>\n                            <th name="th_description" class="text-end">\n                                <span>\n                                    الوصف\n                                </span>\n                                <br/>\n                                <span>\n                                    Description\n                                </span>\n                            </th>\n                        </tr>\n                    </thead>\n                    <tbody class="invoice_tbody">\n                        <t t-set="current_subtotal" t-value="0"/>\n                        <t t-set="lines" t-value="o.invoice_line_ids.sorted(key=lambda l: (-l.sequence, l.date, l.move_name, -l.id), reverse=True)"/>\n\n                        <t t-foreach="lines" t-as="line">\n                            <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>\n                            <t t-set="current_total" t-value="current_subtotal + line.price_total" t-if="o.tax_calculation_rounding_method == 'round_per_line'"/>\n\n                            <tr t-att-class="'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''">\n                                <t t-if="line.display_type not in ('line_note', 'line_section')" name="account_invoice_line_accountable">\n                                    <td class="text-end o_price_total">\n                                        <span class="text-nowrap" t-field="line.price_total"/>\n                                    </td>\n                                    <td class="text-end">\n                                        <span class="text-nowrap" t-field="line.l10n_gcc_invoice_tax_amount"/>\n                                    </td>\n                                    <td class="text-end o_price_total">\n                                        <span class="text-nowrap" t-field="line.price_subtotal"/>\n                                    </td>\n\n                                    <td class="text-end">\n                                        <span t-out="', '.join(map(lambda x: (x.invoice_label or x.name), line.tax_ids))" id="line_tax_ids"/>\n                                    </td>\n                                    <td t-if="display_discount" class="text-end">\n                                        <span class="text-nowrap" t-field="line.discount"/>\n                                    </td>\n                                    <td class="text-end">\n                                        <span class="text-nowrap" t-field="line.price_unit"/>\n                                    </td>\n                                    <td class="text-end">\n                                        <span t-field="line.quantity"/>\n                                        <span t-field="line.product_uom_id" groups="uom.group_uom"/>\n                                    </td>\n                                    <td name="account_invoice_line_name" class="text-end">\n                                        <t t-if="line.product_id">\n                                            <t t-set="english_name" t-value="line.with_context(lang='en_US').product_id.display_name"/>\n                                            <t t-set="arabic_name" t-value="line.with_context(lang='ar_001').product_id.display_name"/>\n\n                                            <span t-out="arabic_name + '\\n'" t-if="arabic_name not in line.name" t-options="{'widget': 'text'}" dir="rtl"/>\n                                            <span t-out="english_name + '\\n'" t-if="(english_name != arabic_name) and (english_name not in line.name)" t-options="{'widget': 'text'}"/>\n                                        </t>\n                                        <span t-out="line.name" t-options="{'widget': 'text'}" t-att-dir="o.env['res.lang']._lang_get_direction(o.partner_id.lang)"/>\n                                    </td>\n\n                                </t>\n                                <t t-if="line.display_type == 'line_section'">\n                                    <td colspan="99">\n                                        <span t-field="line.name" t-options="{'widget': 'text'}"/>\n                                    </td>\n                                    <t t-set="current_section" t-value="line"/>\n                                    <t t-set="current_subtotal" t-value="0"/>\n                                </t>\n                                <t t-if="line.display_type == 'line_note'">\n                                    <td colspan="99">\n                                        <span t-field="line.name" t-options="{'widget': 'text'}"/>\n                                    </td>\n                                </t>\n                            </tr>\n\n                            <t t-if="current_section and (line_last or lines[line_index+1].display_type == 'line_section')">\n                                <tr class="is-subtotal text-end">\n                                    <td colspan="99">\n                                        <strong class="mr16" style="display: inline-block">Subtotal/الإجمالي الفرعي</strong>\n                                        <span t-out="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                    </td>\n                                </tr>\n                            </t>\n                        </t>\n                    </tbody>\n                </table>\n\n                <div class="clearfix pt-4 pb-3">\n                    <div id="total" class="row">\n                        <div class="col-6">\n                            <table class="table table-sm" style="page-break-inside: avoid;">\n                                <tr class="border-black o_subtotal">\n                                    <td class="text-end">\n                                        <span t-field="o.amount_untaxed"/>\n                                    </td>\n                                    <td class="text-end">\n                                        <strong>\n                                            Subtotal\n                                            /\n                                            الإجمالي الفرعي\n                                        </strong>\n                                    </td>\n                                </tr>\n                                <t t-set="tax_totals" t-value="o.tax_totals"/>\n                                <t t-foreach="tax_totals['subtotals']" t-as="subtotal">\n                                    <t t-set="subtotal_to_show" t-value="subtotal['name']"/>\n                                    <!-- copy-pasted template "account.tax_groups_totals" with reversed columns order -->\n                                    <t t-foreach="tax_totals['groups_by_subtotal'][subtotal_to_show]" t-as="amount_by_group">\n                                        <tr>\n                                            <td class="text-end o_price_total">\n                                                <span class="text-nowrap" t-esc="amount_by_group['formatted_tax_group_amount']"/>\n                                            </td>\n                                            <td class="text-end">\n                                                <strong>\n                                                    <span t-esc="amount_by_group['tax_group_name']"/>\n                                                    <t t-if="tax_totals['display_tax_base']">\n                                                        <span class="text-nowrap"> on\n                                                            <t t-esc="amount_by_group['formatted_tax_group_base_amount']"/>\n                                                        </span>\n                                                    </t>\n                                                    <!-- Arabic translation of tax group -->\n                                                    <t t-set="arabic_tax_group_name" t-value="o_sec.tax_totals['groups_by_subtotal'][o_sec.tax_totals['subtotals'][subtotal_index]['name']][amount_by_group_index]['tax_group_name']"/>\n                                                    <span t-if="arabic_tax_group_name != amount_by_group['tax_group_name']" class="text-nowrap">/\n                                                        <t t-esc="arabic_tax_group_name"/>\n                                                    </span>\n                                                </strong>\n                                            </td>\n                                        </tr>\n                                    </t>\n\n                                </t>\n                                <tr class="border-black o_total">\n                                    <td class="text-end">\n                                        <span class="text-nowrap" t-field="o.amount_total"/>\n                                    </td>\n                                    <td class="text-end">\n                                        <strong>\n                                            Total\n                                            /\n                                            المجموع\n                                        </strong>\n                                    </td>\n                                </tr>\n\n                                <t t-if="print_with_payments">\n                                    <t t-if="o.payment_state != 'invoicing_legacy'">\n                                        <t t-set="payments_vals" t-value="o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget['content'] or []"/>\n                                        <t t-foreach="payments_vals" t-as="payment_vals">\n                                            <tr class="border-black o_total">\n                                                <td>\n                                                    <i class="row">\n                                                        <div class="col-7 oe_form_field oe_payment_label">\n                                                            Paid on/دفعت في:\n                                                        </div>\n                                                        <div class="col-5 ps-0 oe_form_field oe_payment_label">\n                                                            <t t-out="payment_vals['date']"/>\n                                                        </div>\n                                                    </i>\n                                                </td>\n                                                <td class="text-end">\n                                                    <span t-out="payment_vals['amount']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                                </td>\n                                            </tr>\n                                        </t>\n                                        <t t-if="len(payments_vals) &gt; 0">\n                                            <tr class="border-black">\n                                                <td>\n                                                    <strong>\n                                                        Amount Due\n                                                        /\n                                                        المبلغ المستحق\n                                                    </strong>\n                                                </td>\n                                                <td class="text-end">\n                                                    <span t-field="o.amount_residual"/>\n                                                </td>\n                                            </tr>\n                                        </t>\n                                    </t>\n                                </t>\n                            </table>\n                        </div>\n                    </div>\n                </div>\n\n                <div class="mb-2">\n                    <p class="lh-sm" t-if="o.company_id.display_invoice_amount_total_words">\n                        Total amount in words: <br/>\n                        <span class="text-muted" t-field="o.amount_total_words"/>\n                    </p>\n                    <p class="text-end lh-sm" t-if="o.company_id.display_invoice_amount_total_words">\n                        المبلغ الإجمالي <br/>\n                        <span class="text-muted" t-out="o._num2words(o.amount_total, 'ar_001')"/>\n                    </p>\n                </div>\n\n                <div t-if="o.currency_id != o.company_id.currency_id" class="row clearfix ms-auto text-nowrap border-top border-bottom p-2">\n                    <t t-set="exchange_rate" t-value="abs(o.amount_total_signed) / o.amount_total if o.amount_total else 0"/>\n                    <div name="exchange_rate" t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'}">\n                        <strong>سعر الصرف</strong><br/>\n                        <strong>Exchange Rate</strong>\n                        <p class="m-0" t-out="exchange_rate" t-options="{&quot;widget&quot;: &quot;float&quot;, &quot;precision&quot;: 5}"/>\n                    </div>\n                    <div name="subtotal_company_currency" t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'}">\n                        <strong>الإجمالي الفرعي</strong><br/>\n                        <strong>Subtotal</strong>\n                        <p class="m-0" t-out="abs(o.amount_untaxed_signed)" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}"/>\n                    </div>\n                    <div name="vat_amount_company_currency" t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'}">\n                        <strong>قيمة الضريبة</strong><br/>\n                        <strong>VAT Amount</strong>\n                        <p class="m-0" t-out="abs(o.amount_tax_signed)" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}"/>\n                    </div>\n                    <div name="total_company_currency" t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'}">\n                        <strong>المجموع</strong><br/>\n                        <strong>Total</strong>\n                        <p class="m-0" t-out="abs(o.amount_total_signed)" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}"/>\n                    </div>\n                </div>\n\n                <p name="payment_communication" t-if="0"/>\n                <div class="row" t-if="o.move_type in ('out_invoice', 'in_refund') and o.payment_reference" name="payment_communication">\n                    <div class="col-2">\n                        <strong>Payment Reference:</strong>\n                    </div>\n                    <div class="col-2">\n                        <span class="fw-bold" t-field="o.payment_reference"/>\n                    </div>\n                    <div class="col-2 text-end">\n                        <strong style="white-space:nowrap">:رقم إشارة الدفعة</strong>\n                    </div>\n                </div>\n\n                <p t-if="o.invoice_payment_term_id" name="payment_term">\n                    <div class="row">\n                        <div class="col-3 text-start">\n                            <span t-out="o.invoice_payment_term_id.note"/>\n                        </div>\n                        <div class="col-3 text-end">\n                            <span t-if="o.invoice_payment_term_id.note != o_sec.invoice_payment_term_id.note" dir="rtl" t-out="o_sec.invoice_payment_term_id.note"/>\n                        </div>\n                    </div>\n                    <t t-if="o.invoice_payment_term_id.display_on_invoice and o.payment_term_details">\n                        <div t-if="o.show_payment_term_details" id="total_payment_term_details_table" class="row">\n                            <div t-attf-class="#{'col-10 offset-2' if report_type != 'html' else 'col-sm-10 col-md-9 offset-sm-2 offset-md-3'}">\n                                <t t-if="o._is_eligible_for_early_payment_discount(o.currency_id,o.invoice_date)">\n                                    <div class="text-end">\n                                        <span dir="rtl" style="white-space: normal;">\n                                            <span t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-out="o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax)">30.00</span> مستحق إذا تم الدفع قبل\n                                            <span t-out="o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)">2024-01-01</span>\n                                        </span>\n                                        <br/>\n                                        <span t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-out="o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax)">30.00</span> due if paid before\n                                        <span t-out="o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)">2024-01-01</span>\n                                    </div>\n                                </t>\n                                <t t-if="len(o.payment_term_details) &gt; 1" t-foreach="o.payment_term_details" t-as="term">\n                                    <div dir="rtl" class="text-end" style="white-space: normal;">\n                                        <span t-out="term_index + 1">1</span> - قسط\n                                        <t t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-out="term.get('amount')">31.05</t> مستحق في\n                                        <t t-out="term.get('date')">2024-01-01</t>\n                                    </div>\n                                    <div class="text-end">\n                                        <span t-out="term_index + 1">1</span> - Installment of\n                                        <t t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-out="term.get('amount')" class="text-end">31.05</t>\n                                        <span> due on </span>\n                                        <t t-out="term.get('date')" class="text-start">2024-01-01</t>\n                                    </div>\n                                </t>\n                            </div>\n                        </div>\n                    </t>\n                </p>\n                <p t-if="o.narration" name="comment">\n                    <div class="row">\n                        <div class="col-6 text-start">\n                            <span t-out="o.narration"/>\n                        </div>\n                        <div class="col-6 text-end">\n                            <span t-if="o.narration 