--
-- Name: stock_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.stock_report AS
 SELECT sm.id,
    sp.name AS picking_name,
    sp.date_done,
    sp.creation_date,
    sp.scheduled_date,
    sp.partner_id,
    sp.is_backorder,
    sp.delay,
    (sp.delay > (0)::numeric) AS is_late,
    sp.cycle_time,
    spt.code AS picking_type_code,
    spt.name AS operation_type,
    p.id AS product_id,
    sm.reference,
    sm.picking_id,
    sm.state,
    sm.product_qty,
    sm.company_id,
    cat.id AS categ_id
   FROM (((((public.stock_move sm
     LEFT JOIN ( SELECT stock_picking.id,
            stock_picking.name,
            stock_picking.date_done,
            stock_picking.date AS creation_date,
            stock_picking.scheduled_date,
            stock_picking.partner_id,
            (stock_picking.backorder_id IS NOT NULL) AS is_backorder,
            ((EXTRACT(epoch FROM avg((stock_picking.date_done - stock_picking.scheduled_date))) / (((24 * 60) * 60))::numeric))::numeric(16,2) AS delay,
            ((EXTRACT(epoch FROM avg((stock_picking.date_done - stock_picking.date))) / (((24 * 60) * 60))::numeric))::numeric(16,2) AS cycle_time
           FROM public.stock_picking
          GROUP BY stock_picking.id, stock_picking.name, stock_picking.date_done, stock_picking.date, stock_picking.scheduled_date, stock_picking.partner_id, (stock_picking.backorder_id IS NOT NULL)) sp ON ((sm.picking_id = sp.id)))
     LEFT JOIN public.stock_picking_type spt ON ((sm.picking_type_id = spt.id)))
     JOIN public.product_product p ON ((sm.product_id = p.id)))
     JOIN public.product_template t ON ((p.product_tmpl_id = t.id)))
     JOIN public.product_category cat ON ((t.categ_id = cat.id)))
  WHERE ((t.type)::text = 'product'::text)
  GROUP BY sm.id, sm.reference, sm.picking_id, sm.state, sm.product_qty, sm.company_id, sp.name, sp.date_done, sp.creation_date, sp.scheduled_date, sp.partner_id, sp.is_backorder, sp.delay, sp.cycle_time, spt.code, spt.name, p.id, (sp.delay > (0)::numeric), cat.id;


